var verses = {
    "2CO.5.17": "Zo dan, indien iemand in Christus is, die is een nieuw schepsel; het oude is voorbijgegaan, ziet, het is alles nieuw geworden.",
    "COL.3.1-2": "Indien gij dan met Christus opgewekt zijt, zo zoekt de dingen, die boven zijn, waar Christus is, zittende aan de rechter hand Gods. Bedenkt de dingen, die boven zijn, niet die op de aarde zijn.",
    "ISA.43.2": "Wanneer gij zult gaan door het water, Ik zal bij u zijn, en door de rivieren, zij zullen u niet overstromen; wanneer gij door het vuur zult gaan, zult gij niet verbranden, en de vlam zal u niet aansteken.",
    "PSA.34.8": "Smaakt en ziet, dat de HEERE goed is; welgelukzalig is de man, die op Hem betrouwt.",
    "ROM.15.4": "Want al wat te voren geschreven is, dat is tot onze lering te voren geschreven, opdat wij, door lijdzaamheid en vertroosting der Schriften, hoop hebben zouden.",
    "PSA.55.22": "Werp uw zorg op den HEERE, en Hij zal u onderhouden; Hij zal in eeuwigheid niet toelaten, dat de rechtvaardige wankele.",
    "ISA.40.8": "Het gras verdort, de bloem valt af; maar het Woord onzes Gods bestaat in der eeuwigheid.",
    "PSA.127.1": "Zo de HEERE het huis niet bouwt, tevergeefs arbeiden deszelfs bouwlieden daaraan; zo de HEERE de stad niet bewaart, tevergeefs waakt de wachter.",
    "ISA.53.6": "Wij dwaalden allen als schapen, wij keerden ons een iegelijk naar zijn weg; doch de HEERE heeft onzer aller ongerechtigheid op Hem doen aanlopen.",
    "PSA.42.1-2": "Gelijk een hert schreeuwt naar de waterstromen, alzo schreeuwt mijn ziel tot U, o God! Mijn ziel dorst naar God, naar den levenden God; wanneer zal ik ingaan, en voor Gods aangezicht verschijnen?",
    "2SA.22.31": "Gods weg is volmaakt; de rede des HEEREN is doorlouterd; Hij is een Schild allen, die op Hem betrouwen.",
    "PSA.40.1-3": "Ik heb den HEERE lang verwacht; en Hij heeft Zich tot mij geneigd, en mijn geroep gehoord. En Hij heeft mij uit een ruisenden kuil, uit modderig slijk opgehaald, en heeft mijn voeten op een rotssteen gesteld, Hij heeft mijn gangen vastgemaakt. En Hij heeft een nieuw lied in mijn mond gegeven, een lofzang onzen Gode; velen zullen het zien, en vrezen, en op den HEERE vertrouwen.",
    "JOB.19.25": "Want ik weet: mijn Verlosser leeft, en Hij zal de laatste over het stof opstaan;",
    "PSA.23.1-3": "De HEERE is mijn Herder, mij zal niets ontbreken. Hij doet mij nederliggen in grazige weiden; Hij voert mij zachtjes aan zeer stille wateren. Hij verkwikt mijn ziel; Hij leidt mij in het spoor der gerechtigheid, om Zijns Naams wil.",
    "MAT.5.44": "Maar Ik zeg u: Hebt uw vijanden lief; zegent ze, die u vervloeken; doet wel dengenen, die u haten; en bidt voor degenen, die u geweld doen, en die u vervolgen;",
    "ISA.55.8-9": "Want Mijn gedachten zijn niet ulieder gedachten, en uw wegen zijn niet Mijn wegen, spreekt de HEERE. Want gelijk de hemelen hoger zijn dan de aarde, alzo zijn Mijn wegen hoger dan uw wegen, en Mijn gedachten dan ulieder gedachten.",
    "LUK.19.10": "Want de Zoon des mensen is gekomen, om te zoeken en zalig te maken, dat verloren was.",
    "HEB.13.5-6": "Uw wandel zij zonder geldgierigheid; en zijt vergenoegd met het tegenwoordige; want Hij heeft gezegd: Ik zal u niet begeven, en Ik zal u niet verlaten. Zodat wij vrijmoediglijk durven zeggen: De Heere is mij een Helper, en ik zal niet vrezen, wat mij een mens zal doen.",
    "1CH.29.11": "Uw, o HEERE, is de grootheid, en de macht, en de heerlijkheid, en de overwinning, en de majesteit; want alles, wat in den hemel en op aarde is, is Uw: Uw, o HEERE, is het Koninkrijk, en Gij hebt U verhoogd tot een Hoofd boven alles.",
    "HEB.13.20-21": "De God nu des vredes, Die den grote Herder der schapen, door het bloed des eeuwigen testaments, uit de doden heeft wedergebracht, namelijk onze Heere Jezus Christus, Die volmake u in alle goed werk, opdat gij Zijn wil moogt doen; werkende in u, hetgeen voor Hem welbehagelijk is, door Jezus Christus; Denwelken zij de heerlijkheid in alle eeuwigheid. Amen.",
    "1CO.1.18": "Want het woord des kruises is wel dengenen, die verloren gaan, dwaasheid; maar ons, die behouden worden, is het een kracht Gods;",
    "MAT.5.14-16": "Gij zijt het licht der wereld; een stad boven op een berg liggende, kan niet verborgen zijn. Noch steekt men een kaars aan, en zet die onder een koornmaat, maar op een kandelaar, en zij schijnt allen, die in het huis zijn; Laat uw licht alzo schijnen voor de mensen, dat zij uw goede werken mogen zien, en uw Vader, Die in de hemelen is, verheerlijken.",
    "COL.3.23-24": "En al wat gij doet, doet dat van harte als den Heere en niet den mensen; Wetende, dat gij van den Heere zult ontvangen de vergelding der erfenis; want gij dient de Heere Christus.",
    "ROM.8.28": "En wij weten, dat dengenen, die God liefhebben, alle dingen medewerken ten goede, namelijk dengenen, die naar Zijn voornemen geroepen zijn.",
    "JHN.11.25-26": "Jezus zeide tot haar: Ik ben de Opstanding en het Leven; die in Mij gelooft zal leven, al ware hij ook gestorven; En een iegelijk, die leeft, en in Mij gelooft, zal niet sterven in der eeuwigheid. Gelooft gij dat?",
    "1CO.13.6-7": "Zij verblijdt zich niet in de ongerechtigheid, maar zij verblijdt zich in de waarheid; Zij bedekt alle dingen, zij gelooft alle dingen, zij hoopt alle dingen, zij verdraagt alle dingen.",
    "MAT.7.12": "Alle dingen dan, die gij wilt, dat u de mensen zouden doen, doet gij hun ook alzo; want dat is de wet en de profeten.",
    "PSA.91.11": "Want Hij zal Zijn engelen van u bevelen, dat zij u bewaren in al uw wegen.",
    "ACT.2.38": "En Petrus zeide tot hen: Bekeert u, en een iegelijk van u worde gedoopt in den Naam van Jezus Christus, tot vergeving der zonden; en gij zult de gave des Heiligen Geestes ontvangen.",
    "1CO.3.16": "Weet gij niet, dat gij Gods tempel zijt, en de Geest Gods in ulieden woont?",
    "ROM.3.23-24": "Want zij hebben allen gezondigd, en derven de heerlijkheid Gods; En worden om niet gerechtvaardigd, uit Zijn genade, door de verlossing, die in Christus Jezus is;",
    "MAT.5.6": "Zalig zijn die hongeren en dorsten naar de gerechtigheid; want zij zullen verzadigd worden.",
    "ISA.26.3": "Het is een bevestigd voornemen, Gij zult allerlei vrede bewaren, want men heeft op U vertrouwd.",
    "PRO.17.22": "Een blij hart zal een medicijn goed maken; maar een verslagen geest zal het gebeente verdrogen.",
    "NEH.8.10": "En Nehemia (dezelve is Hattirsatha) en Ezra, de priester, de schriftgeleerde, en de Levieten, die het volk onderwezen, zeiden tot al het volk: Deze dag is den HEERE, uw God, heilig; bedrijft dan geen rouw, en weent niet; want al het volk weende, als zij de woorden der wet hoorden.",
    "1PE.2.9": "Maar gij zijt een uitverkoren geslacht, een koninklijk priesterdom, een heilig volk, een verkregen volk; opdat gij zoudt verkondigen de deugden Desgenen, Die u uit de duisternis geroepen heeft tot Zijn wonderbaar licht;",
    "PSA.18.2": "De HEERE is mijn Steenrots, en mijn Burg, en mijn Uithelper; mijn God, mijn Rots, op Welken ik betrouw; mijn Schild, en de Hoorn mijns heils, mijn Hoog Vertrek.",
    "1CO.15.58": "Zo dan, mijn geliefde broeders! Zijt standvastig, onbewegelijk, altijd overvloedig zijnde in het werk des Heeren, als die weet, dat uw arbeid niet ijdel is in den Heere.",
    "EXO.14.14": "De HEERE zal voor ulieden strijden, en gij zult stil zijn.",
    "2CH.15.7": "Daarom weest gij sterk, en laat uw handen niet verslappen; want er is loon naar uw werk.",
    "PHP.4.11-12": "Niet dat ik dit zeg vanwege gebrek; want ik heb geleerd vergenoegd te zijn in hetgeen ik ben. En ik weet vernederd te worden, ik weet ook overvloed te hebben; alleszins en in alles ben ik onderwezen, beide verzadigd te zijn en honger te lijden, beide overvloed te hebben en gebrek te lijden.",
    "ISA.58.11": "En de HEERE zal u geduriglijk leiden, en Hij zal uw ziel verzadigen in grote droogten, en uw beenderen vaardig maken; en gij zult zijn als een gewaterde hof, en als een springader der wateren, welker wateren niet ontbreken.",
    "MAT.16.24": "Toen zeide Jezus tot Zijn discipelen: Zo iemand achter Mij wil komen, die verloochene zichzelven, en neme zijn kruis op, en volge Mij.",
    "DEU.31.6": "Weest sterk en hebt goeden moed, en vreest niet, en verschrikt niet voor hun aangezicht; want het is de HEERE, uw God, Die met u gaat; Hij zal u niet begeven, noch u verlaten.",
    "1CO.13.4-5": "De liefde is lankmoedig, zij is goedertieren; de liefde is niet afgunstig; de liefde handelt niet lichtvaardiglijk, zij is niet opgeblazen; Zij handelt niet ongeschiktelijk, zij zoekt zichzelve niet, zij wordt niet verbitterd, zij denkt geen kwaad;",
    "ACT.16.31": "En zij zeiden: Geloof in den Heere Jezus Christus, en gij zult zalig worden, gij en uw huis.",
    "1PE.4.10": "Een iegelijk, gelijk hij gave ontvangen heeft, alzo bediene hij dezelve aan de anderen, als goede uitdelers der menigerlei genade Gods.",
    "PSA.46.1": "God is ons een Toevlucht en Sterkte; Hij is krachtelijk bevonden een Hulp in benauwdheden.",
    "ISA.41.13": "Want Ik, de HEERE, uw God, grijp uw rechterhand aan, Die tot u zeg: Vrees niet, Ik help u.",
    "1CO.15.3-4": "Want ik heb ulieden ten eerste overgegeven, hetgeen ik ook ontvangen heb, dat Christus gestorven is voor onze zonden, naar de Schriften; En dat Hij is begraven, en dat Hij is opgewekt ten derden dage, naar de Schriften;",
    "JER.17.7-8": "Gezegend daarentegen is de man, die op den HEERE vertrouwt, en wiens vertrouwen de HEERE is! Want hij zal zijn als een boom, die aan het water geplant is, en zijn wortelen uitschiet aan een rivier, en gevoelt het niet, wanneer er een hitte komt, maar zijn loof blijft groen; en in een jaar van droogte zorgt hij niet, en houdt niet op van vrucht te dragen.",
    "PHP.1.6": "Vertrouwende ditzelve, dat Hij, Die in u een goed werk begonnen heeft, dat voleindigen zal tot op den dag van Jezus Christus;",
    "2CO.12.9": "En Hij heeft tot mij gezegd: Mijn genade is u genoeg; want Mijn kracht wordt in zwakheid volbracht. Zo zal ik dan veel liever roemen in mijn zwakheden, opdat de kracht van Christus in mij wone.",
    "HEB.4.15-16": "Want wij hebben geen hogepriester, die niet kan medelijden hebben met onze zwakheden, maar Die in alle dingen, gelijk als wij, is verzocht geweest, doch zonder zonde. Laat ons dan met vrijmoedigheid toegaan tot den troon der genade, opdat wij barmhartigheid mogen verkrijgen, en genade vinden, om geholpen te worden ter bekwamer tijd.",
    "PRO.4.23": "Behoed uw hart boven al wat te bewaren is, want daaruit zijn de uitgangen des levens.",
    "ROM.11.33": "O diepte des rijkdoms, beide der wijsheid en der kennis Gods, hoe ondoorzoekelijk zijn Zijn oordelen, en onnaspeurlijk Zijn wegen!",
    "JHN.1.1-3": "In den beginne was het Woord, en het Woord was bij God, en het Woord was God. Dit was in den beginne bij God. Alle dingen zijn door Hetzelve gemaakt, en zonder Hetzelve is geen ding gemaakt, dat gemaakt is.",
    "PSA.56.3-4": "Ten dage, als ik zal vrezen, zal ik op U vertrouwen. In God zal ik Zijn woord prijzen; ik vertrouw op God, ik zal niet vrezen; wat zoude mij vlees doen?",
    "JHN.10.11": "Ik ben de goede Herder; de goede herder stelt zijn leven voor de schapen.",
    "ROM.12.21": "Wordt van het kwade niet overwonnen, maar overwint het kwade door het goede.",
    "MRK.9.23": "En Jezus zeide tot hem: Zo gij kunt geloven, alle dingen zijn mogelijk dengene, die gelooft.",
    "DEU.33.27": "De eeuwige God zij u een woning, en van onder eeuwige armen; en Hij verdrijve den vijand voor uw aangezicht, en zegge: Verdelg!",
    "PRO.17.17": "Een vriend heeft te aller tijd lief; en een broeder wordt in de benauwdheid geboren.",
    "PSA.19.1": "De hemelen vertellen Gods eer, en het uitspansel verkondigt Zijner handen werk.",
    "MAL.3.10": "Brengt al de tienden in het schathuis, opdat er spijze zij in Mijn huis; en beproeft Mij nu daarin, zegt de HEERE der heirscharen, of Ik u dan niet opendoen zal de vensteren des hemels, en u zegen afgieten, zodat er geen schuren genoeg wezen zullen.",
    "JOS.24.15": "Doch zo het kwaad is in uw ogen den HEERE te dienen, kiest u heden, wien gij dienen zult; hetzij de goden, welke uw vaders, die aan de andere zijde der rivier waren, gediend hebben, of de goden der Amorieten, in welker land gij woont; maar aangaande mij, en mijn huis, wij zullen den HEERE dienen!",
    "ECC.12.13": "Van alles, wat gehoord is, is het einde van de zaak: Vrees God, en houd Zijn geboden, want dit betaamt allen mensen.",
    "PSA.37.23-24": "De gangen deszelven mans worden van den HEERE bevestigd; en Hij heeft lust aan zijn weg. Als hij valt, zo wordt hij niet weggeworpen, want de HEERE ondersteunt zijn hand.",
    "REV.21.5": "En Die op den troon zat, zeide: Ziet, Ik maak alle dingen nieuw. En Hij zeide tot mij: Schrijf, want deze woorden zijn waarachtig en getrouw.",
    "ISA.40.31": "Maar dien den HEERE verwachten, zullen de kracht vernieuwen; zij zullen opvaren met vleugelen, gelijk de arenden; zij zullen lopen, en niet moede worden; zij zullen wandelen, en niet mat worden.",
    "JHN.4.13-14": "Jezus antwoordde, en zeide tot haar: Een ieder, die van dit water drinkt, zal wederom dorsten: Maar zo wie gedronken zal hebben van het water, dat Ik hem geven zal, dien zal in eeuwigheid niet dorsten; maar het water, dat Ik hem zal geven, zal in hem worden een fontein van water, springende tot in het eeuwige leven.",
    "HEB.12.1-2": "Daarom dan ook, alzo wij zo groot een wolk der getuigen rondom ons hebben liggende, laat ons afleggen allen last, en de zonde, die ons lichtelijk omringt, en laat ons met lijdzaamheid lopen de loopbaan, die ons voorgesteld is; Ziende op den oversten Leidsman en Voleinder des geloofs, Jezus, Dewelke, voor de vreugde, die Hem voorgesteld was, het kruis heeft verdragen, en schande veracht, en is gezeten aan de rechter hand des troons van God.",
    "1JN.4.18": "Er is in de liefde geen vrees, maar de volmaakte liefde drijft de vrees buiten; want de vrees heeft pijn, en die vreest, is niet volmaakt in de liefde.",
    "PSA.118.24": "Dit is de dag, dien de HEERE gemaakt heeft; laat ons op denzelven ons verheugen, en verblijd zijn.",
    "HEB.12.11": "En alle kastijding als die tegenwoordig is, schijnt geen zaak van vreugde, maar van droefheid te zijn; doch daarna geeft zij van zich een vreedzame vrucht der gerechtigheid dengenen, die door dezelve geoefend zijn.",
    "ECC.4.9-10": "Twee zijn beter dan een; want zij hebben een goede beloning van hun arbeid; Want indien zij vallen, de een richt zijn metgezel op; maar wee den ene, die gevallen is, want er is geen tweede om hem op te helpen.",
    "2CO.1.3-4": "Geloofd zij de God en Vader van onzen Heere Jezus Christus, de Vader der barmhartigheden, en de God aller vertroosting; Die ons vertroost in al onze verdrukking, opdat wij zouden kunnen vertroosten degenen, die in allerlei verdrukking zijn, door de vertroosting, met welke wij zelven van God vertroost worden.",
    "PSA.30.5": "Want een ogenblik is er in Zijn toorn, maar een leven in Zijn goedgunstigheid; des avonds vernacht het geween, maar des morgens is er gejuich.",
    "GAL.6.2": "Draagt elkanders lasten, en vervult alzo de wet van Christus.",
    "JHN.14.27": "Vrede laat Ik u, Mijn vrede geef Ik u; niet gelijkerwijs de wereld hem geeft, geef Ik hem u. Uw hart worde niet ontroerd en zij niet versaagd.",
    "GAL.3.26-28": "Want gij zijt allen kinderen Gods door het geloof in Christus Jezus. Want zovelen als gij in Christus gedoopt zijt, hebt gij Christus aangedaan. Daarin is noch Jood noch Griek; daarin is noch dienstbare noch vrije; daarin is geen man en vrouw; want gij allen zijt een in Christus Jezus.",
    "EXO.33.14": "Hij dan zeide: Zou Mijn aangezicht moeten medegaan, om u gerust te stellen?",
    "LUK.1.37": "Want geen ding zal bij God onmogelijk zijn.",
    "PRO.16.3": "Wentel uw werken op den HEERE, en uw gedachten zullen bevestigd worden.",
    "ACT.17.27-28": "Opdat zij den Heere zouden zoeken, of zij Hem immers tasten en vinden mochten; hoewel Hij niet verre is van een iegelijk van ons. Want in Hem leven wij, en bewegen ons, en zijn wij; gelijk ook enigen van uw poeten gezegd hebben: Want wij zijn ook Zijn geslacht.",
    "JHN.5.24": "Voorwaar, voorwaar zeg Ik u: Die Mijn woord hoort, en gelooft Hem, Die Mij gezonden heeft, die heeft het eeuwige leven, en komt niet in de verdoemenis, maar is uit den dood overgegaan in het leven.",
    "MRK.1.15": "En zeggende: De tijd is vervuld, en het Koninkrijk Gods nabij gekomen; bekeert u, en gelooft het Evangelie.",
    "PRO.16.9": "Het hart des mensen overdenkt zijn weg; maar de HEERE stiert zijn gang.",
    "PSA.46.10": "Laat af, en weet, dat Ik God ben; Ik zal verhoogd worden onder de heidenen, Ik zal verhoogd worden op de aarde.",
    "2TH.3.16": "De Heere nu des vredes Zelf geve u vrede te allen tijd, in allerlei wijze. De Heere zij met u allen.",
    "1TH.5.16-18": "Verblijdt u te allen tijd. Bidt zonder ophouden. Dankt God in alles; want dit is de wil van God in Christus Jezus over u.",
    "PHP.3.13-14": "Broeders, ik acht niet, dat ik zelf het gegrepen heb. Maar een ding doe ik, vergetende, hetgeen achter is, en strekkende mij tot hetgeen voor is, jaag ik naar het wit, tot den prijs der roeping Gods, die van boven is in Christus Jezus.",
    "MAT.24.35": "De hemel en de aarde zullen voorbijgaan, maar Mijn woorden zullen geenszins voorbijgaan.",
    "EPH.5.1-2": "Zijt dan navolgers Gods, als geliefde kinderen; En wandelt in de liefde, gelijkerwijs ook Christus ons liefgehad heeft, en Zichzelven voor ons heeft overgegeven tot een offerande en een slachtoffer, Gode tot een welriekenden reuk.",
    "PRO.18.10": "De Naam des HEEREN is een Sterke Toren; de rechtvaardige zal daarhenen lopen, en in een Hoog Vertrek gesteld worden.",
    "JHN.15.4-5": "Blijft in Mij, en Ik in u. Gelijkerwijs de rank geen vrucht kan dragen van zichzelve, zo zij niet in den wijnstok blijft; alzo ook gij niet, zo gij in Mij niet blijft. Ik ben de Wijnstok, en gij de ranken; die in Mij blijft, en Ik in hem, die draagt veel vrucht; want zonder Mij kunt gij niets doen.",
    "PSA.37.4": "En verlustig u in den HEERE, zo zal Hij u geven de begeerten uws harten.",
    "1JN.4.9-10": "Hierin is de liefde Gods jegens ons geopenbaard, dat God Zijn eniggeboren Zoon gezonden heeft in de wereld, opdat wij zouden leven door Hem. Hierin is de liefde, niet dat wij God liefgehad hebben, maar dat Hij ons lief heeft gehad, en Zijn Zoon gezonden heeft tot een verzoening voor onze zonden.",
    "JHN.17.3": "En dit is het eeuwige leven, dat zij U kennen, den enigen waarachtigen God, en Jezus Christus, Dien Gij gezonden hebt.",
    "2CO.4.6": "Want God, Die gezegd heeft, dat het licht uit de duisternis zou schijnen, is Degene, Die in onze harten geschenen heeft, om te geven verlichting der kennis der heerlijkheid Gods in het aangezicht van Jezus Christus.",
    "COL.3.12-13": "Zo doet dan aan, als uitverkorenen Gods, heiligen en beminden, de innerlijke bewegingen der barmhartigheid, goedertierenheid, ootmoedigheid, zachtmoedigheid, lankmoedigheid; Verdragende elkander, en vergevende de een den anderen, zo iemand tegen iemand enige klacht heeft; gelijkerwijs als Christus u vergeven heeft, doet ook gij alzo.",
    "PSA.1.1-2": "Welgelukzalig is de man, die niet wandelt in de raad der goddelozen, noch staat op den weg der zondaren, noch zit in het gestoelte der spotters; Maar zijn lust is in des HEEREN wet, en hij overdenkt Zijn wet dag en nacht.",
    "PRO.3.11-12": "Mijn zoon! verwerp de tucht des HEEREN niet, en wees niet verdrietig over Zijn kastijding; Want de HEERE kastijdt dengene, dien Hij liefheeft, ja, gelijk een vader den zoon, in denwelken hij een welbehagen heeft.",
    "ECC.3.11": "Hij heeft ieder ding schoon gemaakt op zijn tijd; ook heeft Hij de eeuw in hun hart gelegd, zonder dat een mens het werk, dat God gemaakt heeft, kan uitvinden, van het begin tot het einde toe.",
    "JOL.2.13": "En scheurt uw hart en niet uw klederen, en bekeert u tot den HEERE, uw God; want Hij is genadig en barmhartig, lankmoedig en groot van goedertierenheid, en berouw hebbende over het kwade.",
    "GAL.6.9-10": "Doch laat ons, goed doende, niet vertragen; want te zijner tijd zullen wij maaien, zo wij niet verslappen. Zo dan, terwijl wij tijd hebben, laat ons goed doen aan allen, maar meest aan de huisgenoten des geloofs.",
    "PSA.136.1": "Looft den HEERE, want Hij is goed; want Zijn goedertierenheid is in der eeuwigheid;",
    "PHP.4.13": "Ik vermag alle dingen door Christus, Die mij kracht geeft.",
    "EPH.4.32": "Maar zijt jegens elkander goedertieren, barmhartig, vergevende elkander, gelijkerwijs ook God in Christus ulieden vergeven heeft.",
    "JAS.1.12": "Zalig is de man, die verzoeking verdraagt; want als hij beproefd zal geweest zijn, zal hij de kroon des levens ontvangen, welke de Heere beloofd heeft dengenen, die Hem liefhebben.",
    "JHN.1.12": "Maar zovelen Hem aangenomen hebben, dien heeft Hij macht gegeven kinderen Gods te worden, namelijk die in Zijn Naam geloven;",
    "EPH.3.17-19": "Opdat Christus door het geloof in uw harten wone, en gij in de liefde geworteld en gegrond zijt; Opdat gij ten volle kondet begrijpen met al de heiligen, welke de breedte, en lengte, en diepte, en hoogte zij, En bekennen de liefde van Christus, die de kennis te boven gaat, opdat gij vervuld wordt tot al de volheid Gods.",
    "PHP.2.9-11": "Daarom heeft Hem ook God uitermate verhoogd, en heeft Hem een Naam gegeven, welke boven allen naam is; Opdat in de Naam van Jezus zich zou buigen alle knie dergenen, die in den hemel, en die op de aarde, en die onder de aarde zijn. En alle tong zou belijden, dat Jezus Christus de Heere zij, tot heerlijkheid Gods des Vaders.",
    "PRO.31.30": "De bevalligheid is bedrog, en de schoonheid ijdelheid; maar een vrouw, die den HEERE vreest, die zal geprezen worden.",
    "MAT.28.19-20": "Gaat dan henen, onderwijst al de volken, dezelve dopende in de Naam des Vaders, en des Zoons, en des Heiligen Geestes; lerende hen onderhouden alles, wat Ik u geboden heb. En ziet, Ik ben met ulieden al de dagen tot de voleinding der wereld. Amen.",
    "1JN.3.16": "Hieraan hebben wij de liefde gekend, dat Hij Zijn leven voor ons gesteld heeft; en wij zijn schuldig voor de broeders het leven te stellen.",
    "EPH.4.1-3": "Zo bid ik u dan, ik, de gevangene in den Heere, dat gij wandelt waardiglijk der roeping, met welke gij geroepen zijt; Met alle ootmoedigheid en zachtmoedigheid, met lankmoedigheid, verdragende elkander in liefde; U benaarstigende te behouden de enigheid des Geestes door den band des vredes.",
    "PSA.100.4-5": "Gaat in tot Zijn poorten met lof, in Zijn voorhoven met lofgezang; looft Hem, prijst Zijn Naam. Want de HEERE is goed; Zijn goedertierenheid is in der eeuwigheid, en Zijn getrouwheid van geslacht tot geslacht.",
    "HAB.3.17-18": "Alhoewel de vijgeboom niet bloeien zal, en geen vrucht aan den wijnstok zijn zal, dat het werk des olijfbooms liegen zal, en de velden geen spijze voortbrengen; dat men de kudde uit de kooi afscheuren zal, en dat er geen rund in de stallingen wezen zal; Zo zal ik nochtans in den HEERE van vreugde opspringen, ik zal mij verheugen in den God mijns heils.",
    "ROM.6.23": "Want de bezoldiging der zonde is de dood, maar de genadegift Gods is het eeuwige leven, door Jezus Christus, onzen Heere.",
    "LAM.3.22-23": "Het zijn de goedertierenheden des HEEREN, dat wij niet vernield zijn, dat Zijn barmhartigheden geen einde hebben; Zij zijn allen morgen nieuw, Uw trouw is groot.",
    "1JN.3.1": "Ziet, hoe grote liefde ons de Vader gegeven heeft, namelijk dat wij kinderen Gods genaamd zouden worden. Daarom kent ons de wereld niet, omdat zij Hem niet kent.",
    "PSA.150.6": "Alles, wat adem heeft, love den HEERE! Hallelujah!",
    "2CO.4.16-18": "Daarom vertragen wij niet; maar hoewel onze uitwendige mens verdorven wordt, zo wordt nochtans de inwendige vernieuwd van dag tot dag. Want onze lichte verdrukking, die zeer haast voorbij gaat, werkt ons een gans zeer uitnemend eeuwig gewicht der heerlijkheid; Dewijl wij niet aanmerken de dingen, die men ziet, maar de dingen, die men niet ziet; want de dingen, die men ziet, zijn tijdelijk, maar de dingen, die men niet ziet, zijn eeuwig.",
    "JER.29.12-13": "Dan zult gij Mij aanroepen, en henengaan, en tot Mij bidden; en Ik zal naar u horen. En gij zult Mij zoeken en vinden, wanneer gij naar Mij zult vragen met uw ganse hart.",
    "REV.21.4": "En God zal alle tranen van hun ogen afwissen; en de dood zal niet meer zijn; noch rouw, noch gekrijt, noch moeite zal meer zijn; want de eerste dingen zijn weggegaan.",
    "PSA.84.11": "Want God, de HEERE, is een Zon en Schild; de HEERE zal genade en eer geven; Hij zal het goede niet onthouden dengenen, die in oprechtheid wandelen.",
    "1TI.6.12": "Strijd den goeden strijd des geloofs, grijp naar het eeuwige leven, tot hetwelk gij ook geroepen zijt, en de goede belijdenis beleden hebt voor vele getuigen.",
    "LAM.3.25-26": "De HEERE is goed dengenen, die Hem verwachten, der ziele, die Hem zoekt. Het is goed, dat men hope, en stille zij op het heil des HEEREN.",
    "2CO.3.17": "De Heere nu is de Geest; en waar de Geest des Heeren is, aldaar is vrijheid.",
    "PSA.91.1-2": "Die in de schuilplaats des Allerhoogsten is gezeten, die zal vernachten in de schaduw des Almachtigen. Ik zal tot den HEERE zeggen: Mijn Toevlucht en mijn Burg! mijn God, op Welken ik vertrouw!",
    "EPH.1.3": "Gezegend zij de God en Vader van onzen Heere Jezus Christus, Die ons gezegend heeft met alle geestelijke zegening in den hemel in Christus.",
    "MAT.4.4": "Doch Hij, antwoordende, zeide: Er is geschreven: De mens zal bij brood alleen niet leven, maar bij alle woord, dat door den mond Gods uitgaat.",
    "ISA.49.15-16": "Kan ook een vrouw haar zuigeling vergeten, dat zij zich niet ontferme over den zoon haars buiks? Ofschoon deze vergate, zo zal Ik toch u niet vergeten. Zie, Ik heb u in de beide handpalmen gegraveerd; uw muren zijn steeds voor Mij.",
    "HEB.10.24-25": "En laat ons op elkander acht nemen, tot opscherping der liefde en der goede werken; En laat ons onze onderlinge bijeenkomst niet nalaten, gelijk sommigen de gewoonte hebben, maar elkander vermanen; en dat zoveel te meer, als gij ziet, dat de dag nadert.",
    "ROM.1.16": "Want ik schaam mij des Evangelies van Christus niet; want het is een kracht Gods tot zaligheid een iegelijk, die gelooft, eerst den Jood, en ook den Griek.",
    "2TI.1.7": "Want God heeft ons niet gegeven een geest der vreesachtigheid, maar der kracht, en der liefde, en der gematigdheid.",
    "ISA.40.28-29": "Weet gij het niet? Hebt gij niet gehoord, dat de eeuwige God, de HEERE, de Schepper van de einden der aarde, noch moede noch mat wordt? Er is geen doorgronding van Zijn verstand. Hij geeft den moeden kracht, en Hij vermenigvuldigt de sterkte dien, die geen krachten heeft.",
    "JHN.8.31-32": "Jezus dan zeide tot de Joden, die in Hem geloofden: Indien gijlieden in Mijn woord blijft, zo zijt gij waarlijk Mijn discipelen; En zult de waarheid verstaan, en de waarheid zal u vrijmaken.",
    "HEB.11.1": "Het geloof nu is een vaste grond der dingen, die men hoopt, en een bewijs der zaken, die men niet ziet.",
    "ISA.40.11": "Hij zal Zijn kudde weiden gelijk een herder; Hij zal de lammeren in Zijn armen vergaderen, en in Zijn schoot dragen; de zogenden zal Hij zachtjes leiden.",
    "JHN.13.34-35": "Een nieuw gebod geef Ik u, dat gij elkander liefhebt; gelijk Ik u liefgehad heb, dat ook gij elkander liefhebt. Hieraan zullen zij allen bekennen, dat gij Mijn discipelen zijt, zo gij liefde hebt onder elkander.",
    "JER.1.5": "Eer Ik u in moeders buik formeerde, heb Ik u gekend, en eer gij uit de baarmoeder voortkwaamt, heb Ik u geheiligd; Ik heb u den volken tot een profeet gesteld.",
    "EPH.4.29": "Geen vuile rede ga uit uw mond, maar zo er enige goede rede is tot nuttige stichting, opdat zij genade geve dien, die dezelve horen.",
    "JHN.10.10": "De dief komt niet, dan opdat hij stele, en slachte, en verderve; Ik ben gekomen, opdat zij het leven hebben, en overvloed hebben.",
    "HEB.11.6": "Maar zonder geloof is het onmogelijk Gode te behagen. Want die tot God komt, moet geloven, dat Hij is, en een Beloner is dergenen, die Hem zoeken.",
    "ISA.55.6-7": "Zoekt den HEERE, terwijl Hij te vinden is; roept Hem aan, terwijl Hij nabij is. De goddeloze verlate zijn weg, en de ongerechtige man zijn gedachten; en hij bekere zich tot den HEERE, zo zal Hij Zich Zijner ontfermen, en tot onzen God, want Hij vergeeft menigvuldiglijk.",
    "JHN.15.16": "Gij hebt Mij niet uitverkoren, maar Ik heb u uitverkoren, en Ik heb u gesteld, dat gij zoudt heengaan en vrucht dragen, en dat uw vrucht blijve; opdat, zo wat gij van den Vader begeren zult in Mijn Naam, Hij u dat geve.",
    "1CO.13.13": "En nu blijft geloof, hoop en liefde, deze drie; doch de meeste van deze is de liefde.",
    "ROM.8.38-39": "Want ik ben verzekerd, dat noch dood, noch leven, noch engelen, noch overheden, noch machten, noch tegenwoordige, noch toekomende dingen, Noch hoogte, noch diepte, noch enig ander schepsel ons zal kunnen scheiden van de liefde Gods, welke is in Christus Jezus, onzen Heere.",
    "MAT.6.26": "Aanziet de vogelen des hemels, dat zij niet zaaien, noch maaien, noch verzamelen in de schuren; en uw hemelse Vader voedt nochtans dezelve; gaat gij dezelve niet zeer veel te boven?",
    "1TI.1.15": "Dit is een getrouw woord, en alle aanneming waardig, dat Christus Jezus in de wereld gekomen is, om de zondaren zalig te maken, van welke ik de voornaamste ben.",
    "JAS.1.22": "En zijt daders des Woords, en niet alleen hoorders, uzelven met valse overlegging bedriegende.",
    "PSA.145.18": "De HEERE is nabij allen, die Hem aanroepen, allen, die Hem aanroepen in der waarheid.",
    "MAT.22.37-39": "En Jezus zeide tot hem: Gij zult liefhebben den Heere, uw God, met geheel uw hart, en met geheel uw ziel, en met geheel uw verstand. Dit is het eerste en het grote gebod. En het tweede aan dit gelijk, is: Gij zult uw naaste liefhebben als uzelven.",
    "PSA.16.11": "Gij zult mij het pad des levens bekend maken; verzadiging der vreugde is bij Uw aangezicht; liefelijkheden zijn in Uw rechterhand, eeuwiglijk.",
    "GEN.1.1": "In den beginne schiep God den hemel en de aarde.",
    "JAS.1.5": "En indien iemand van u wijsheid ontbreekt, dat hij ze van God begere, Die een iegelijk mildelijk geeft, en niet verwijt; en zij zal hem gegeven worden.",
    "MAT.18.20": "Want waar twee of drie vergaderd zijn in Mijn Naam, daar ben Ik in het midden van hen.",
    "PSA.121.1-2": "Ik hef mijn ogen op naar de bergen, van waar mijn hulp komen zal. Mijn hulp is van den HEERE, Die hemel en aarde gemaakt heeft.",
    "GAL.5.22-23": "Maar de vrucht des Geestes is liefde, blijdschap, vrede, lankmoedigheid, goedertierenheid, goedheid, geloof, zachtmoedigheid, matigheid. Tegen de zodanigen is de wet niet.",
    "ISA.64.8": "Doch nu, HEERE! Gij zijt onze Vader; wij zijn leem, en Gij zijt onze pottenbakker, en wij allen zijn Uwer handen werk.",
    "ROM.10.13": "Want een iegelijk, die den Naam des Heeren zal aanroepen, zal zalig worden.",
    "COL.3.17": "En al wat gij doet met woorden of met werken, doet het alles in de Naam van de Heere Jezus, dankende God en de Vader door Hem.",
    "MAT.7.7-8": "Bidt, en u zal gegeven worden; zoekt, en gij zult vinden; klopt, en u zal opengedaan worden. Want een iegelijk, die bidt, die ontvangt; en die zoekt, die vindt; en die klopt, dien zal opengedaan worden.",
    "JHN.20.29": "Jezus zeide tot hem: Omdat gij Mij gezien hebt, Thomas, zo hebt gij geloofd; zalig zijn zij, die niet zullen gezien hebben, en nochtans zullen geloofd hebben.",
    "JER.33.3": "Roep tot Mij, en Ik zal u antwoorden, en Ik zal u bekend maken grote en vaste dingen, die gij niet weet.",
    "EZK.36.26": "En Ik zal u een nieuw hart geven, en zal een nieuwen geest geven in het binnenste van u; en Ik zal het stenen hart uit uw vlees wegnemen, en zal u een vlesen hart geven.",
    "ROM.5.8": "Maar God bevestigt Zijn liefde jegens ons, dat Christus voor ons gestorven is, als wij nog zondaars waren.",
    "PSA.119.105": "Uw woord is een lamp voor mijn voet, en een licht voor mijn pad.",
    "ROM.12.1-2": "Ik bid u dan, broeders, door de ontfermingen Gods, dat gij uw lichamen stelt tot een levende, heilige en Gode welbehagelijke offerande, welke is uw redelijke godsdienst. En wordt dezer wereld niet gelijkvormig; maar wordt veranderd door de vernieuwing uws gemoeds, opdat gij moogt beproeven, welke de goede, en welbehagelijke en volmaakte wil van God zij.",
    "PSA.119.11": "Ik heb Uw rede in mijn hart verborgen, opdat ik tegen U niet zondigen zou.",
    "1CO.16.13-14": "Waakt, staat in het geloof, houdt u mannelijk, zijt sterk. Dat al uw dingen in de liefde geschieden.",
    "MAT.11.28-30": "Komt herwaarts tot Mij, allen die vermoeid en belast zijt, en Ik zal u rust geven. Neemt Mijn juk op u, en leert van Mij, dat Ik zachtmoedig ben en nederig van hart; en gij zult rust vinden voor uw zielen. Want Mijn juk is zacht, en Mijn last is licht.",
    "1SA.16.7": "Doch de HEERE zeide tot Samuel: Zie zijn gestalte niet aan, noch de hoogte zijner statuur, want Ik heb hem verworpen; want het is niet gelijk de mens ziet; want de mens ziet aan, wat voor ogen is, maar de HEERE ziet het hart aan.",
    "LUK.1.46-47": "En Maria zeide: Mijn ziel maakt groot den Heere; En mijn geest verheugt zich in God, mijn Zaligmaker;",
    "GEN.1.27": "En God schiep den mens naar Zijn beeld; naar het beeld van God schiep Hij hem; man en vrouw schiep Hij ze.",
    "GAL.2.20": "Ik ben met Christus gekruist; en ik leef, doch niet meer ik, maar Christus leeft in mij; en hetgeen ik nu in het vlees leef, dat leef ik door het geloof des Zoons van God, Die mij liefgehad heeft, en Zichzelven voor mij overgegeven heeft.",
    "1CO.2.9": "Maar gelijk geschreven is: Hetgeen het oog niet heeft gezien, en het oor niet heeft gehoord, en in het hart des mensen niet is opgeklommen, hetgeen God bereid heeft dien, die Hem liefhebben.",
    "COL.3.16": "Het woord van Christus wone rijkelijk in u, in alle wijsheid; leert en vermaant elkander, met psalmen en lofzangen, en geestelijke liederen, zingende den Heere met aangenaamheid in uw hart.",
    "NUM.6.24-26": "De HEERE zegene u, en behoede u! De HEERE doe Zijn aangezicht over u lichten, en zij u genadig! De HEERE verheffe Zijn aangezicht over u, en geve u vrede!",
    "LUK.11.28": "Maar Hij zeide: Ja, zalig zijn degenen, die het Woord Gods horen, en hetzelve bewaren.",
    "PSA.63.1": "O God! Gij zijt mijn God! ik zoek U in den dageraad; mijn ziel dorst naar U; mijn vlees verlangt naar U, in een land, dor en mat, zonder water.",
    "JHN.8.36": "Indien dan de Zoon u zal vrijgemaakt hebben, zo zult gij waarlijk vrij zijn.",
    "PRO.15.1": "Een zacht antwoord keert de grimmigheid af; maar een smartend woord doet den toorn oprijzen.",
    "ISA.43.18-19": "Gedenkt der vorige dingen niet, en overlegt de oude dingen niet. Ziet, Ik zal wat nieuws maken, nu zal het uitspruiten, zult gijlieden dat niet weten? Ja, Ik zal in de woestijn een weg leggen, en rivieren in de wildernis.",
    "JAS.1.19-20": "Zo dan, mijn geliefde broeders, een iegelijk mens zij ras om te horen, traag om te spreken, traag tot toorn; Want de toorn des mans werkt Gods gerechtigheid niet.",
    "EPH.2.10": "Want wij zijn Zijn maaksel, geschapen in Christus Jezus tot goede werken, welke God voorbereid heeft, opdat wij in dezelve zouden wandelen.",
    "ROM.10.17": "Zo is dan het geloof uit het gehoor, en het gehoor door het Woord Gods.",
    "JAS.1.2-4": "Acht het voor grote vreugde, mijn broeders, wanneer gij in velerlei verzoekingen valt; Wetende, dat de beproeving uws geloofs lijdzaamheid werkt. Doch de lijdzaamheid hebbe een volmaakt werk, opdat gij moogt volmaakt zijn en geheel oprecht, in geen ding gebrekkelijk.",
    "1TH.5.11": "Daarom vermaant elkander, en sticht de een den anderen, gelijk gij ook doet.",
    "1PE.1.3": "Geloofd zij de God en Vader van onzen Heere Jezus Christus, Die naar Zijn grote barmhartigheid ons heeft wedergeboren, tot een levende hoop, door de opstanding van Jezus Christus uit de doden.",
    "JHN.1.5": "En het Licht schijnt in de duisternis, en de duisternis heeft hetzelve niet begrepen.",
    "LEV.19.18": "Gij zult niet wreken, noch toorn behouden tegen de kinderen uws volks; maar gij zult uw naaste liefhebben als uzelven; Ik ben de HEERE!",
    "MAT.5.8": "Zalig zijn de reinen van hart; want zij zullen God zien.",
    "ISA.61.1": "De Geest des Heeren HEEREN is op Mij, omdat de Heere Mij gezalfd heeft, om een blijde boodschap te brengen den zachtmoedigen; Hij heeft Mij gezonden om te verbinden de gebrokenen van harte, om den gevangenen vrijheid uit te roepen, en den gebondenen opening der gevangenis;",
    "RUT.1.16": "Maar Ruth zeide: Val mij niet tegen, dat ik u zou verlaten, om van achter u weder te keren; want waar gij zult heengaan, zal ik ook heengaan, en waar gij zult vernachten, zal ik vernachten; uw volk is mijn volk, en uw God mijn God.",
    "JHN.8.12": "Jezus dan sprak wederom tot henlieden, zeggende: Ik ben het licht der wereld; die Mij volgt, zal in de duisternis niet wandelen, maar zal het licht des levens hebben.",
    "2TH.3.3": "Maar de Heere is getrouw, Die u zal versterken en bewaren van den boze.",
    "PSA.34.4": "Ik heb den HEERE gezocht, en Hij heeft mij geantwoord, en mij uit al mijn vrezen gered.",
    "TIT.3.5": "Heeft Hij ons zalig gemaakt, niet uit de werken der rechtvaardigheid, die wij gedaan hadden, maar naar Zijn barmhartigheid, door het bad der wedergeboorte en vernieuwing des Heiligen Geestes;",
    "LUK.12.32": "Vreest niet, gij klein kuddeken, want het is uws Vaders welbehagen, ulieden het Koninkrijk te geven.",
    "PSA.23.6": "Immers zullen mij het goede en de weldadigheid volgen al de dagen mijns levens; en ik zal in het huis des HEEREN blijven in lengte van dagen.",
    "MIC.7.18-19": "Wie is een God gelijk Gij, Die de ongerechtigheid vergeeft, en de overtreding van het overblijfsel Zijner erfenis voorbijgaat? Hij houdt Zijn toorn niet in eeuwigheid; want Hij heeft lust aan goedertierenheid. Hij zal Zich onzer weder ontfermen; Hij zal onze ongerechtigheden dempen; ja, Gij zult al hun zonden in de diepten der zee werpen.",
    "2CO.4.7": "Maar wij hebben dezen schat in aarden vaten, opdat de uitnemendheid der kracht zij van God, en niet uit ons;",
    "GEN.50.20": "Gijlieden wel, gij hebt kwaad tegen mij gedacht; doch God heeft dat ten goede gedacht; opdat Hij deed, gelijk het te dezen dage is, om een groot volk in het leven te behouden.",
    "PSA.32.8": "Ik zal u onderwijzen, en u leren van den weg, dien gij gaan zult; Ik zal raad geven, Mijn oog zal op u zijn.",
    "MAT.6.19-21": "Vergadert u geen schatten op de aarde, waar ze de mot en de roest verderft, en waar de dieven doorgraven en stelen; Maar vergadert u schatten in den hemel, waar ze noch mot noch roest verderft, en waar de dieven niet doorgraven noch stelen; Want waar uw schat is, daar zal ook uw hart zijn.",
    "ROM.15.13": "De God nu der hoop vervulle ulieden met alle blijdschap en vrede in het geloven, opdat gij overvloedig moogt zijn in de hoop, door de kracht des Heiligen Geestes.",
    "JHN.3.30": "Hij moet wassen, maar ik minder worden.",
    "DEU.7.9": "Gij zult dan weten, dat de HEERE, uw God, die God is, die getrouwe God, welke het verbond en de weldadigheid houdt dien, die Hem liefhebben, en Zijn geboden houden tot in duizend geslachten.",
    "HEB.13.8": "Jezus Christus is gisteren en heden dezelfde en in der eeuwigheid.",
    "EPH.2.4-5": "Maar God, Die rijk is in barmhartigheid door Zijn grote liefde, waarmede Hij ons liefgehad heeft, Ook toen wij dood waren door de misdaden, heeft ons levend gemaakt met Christus; (uit genade zijt gij zalig geworden)",
    "PRO.10.12": "Haat verwekt krakelen; maar de liefde dekt alle overtredingen toe.",
    "3JN.1.4": "Ik heb geen meerdere blijdschap dan hierin, dat ik hoor, dat mijn kinderen in de waarheid wandelen.",
    "ECC.3.1": "Alles heeft een bestemden tijd, en alle voornemen onder den hemel heeft zijn tijd.",
    "PSA.4.8": "Ik zal in vrede te zamen nederliggen en slapen; want Gij, o HEERE! alleen zult mij doen zeker wonen.",
    "1CO.15.55-57": "Dood, waar is uw prikkel? Hel, waar is uw overwinning? De prikkel nu des doods is de zonde; en de kracht der zonde is de wet. Maar Gode zij dank, Die ons de overwinning geeft door onzen Heere Jezus Christus.",
    "JER.29.11": "Want Ik weet de gedachten, die Ik over u denk, spreekt de HEERE, gedachten des vredes, en niet des kwaads, dat Ik u geve het einde en de verwachting.",
    "PRO.11.25": "De zegenende ziel zal vet gemaakt worden; en die bevochtigt, zal ook zelf een vroege regen worden.",
    "2PE.3.18": "Maar wast op in de genade en kennis van onzen Heere en Zaligmaker Jezus Christus. Hem zij de heerlijkheid, beide nu en in de dag der eeuwigheid. Amen.",
    "2TI.2.15": "Benaarstig u, om uzelven Gode beproefd voor te stellen, een arbeider, die niet beschaamd wordt, die het Woord der waarheid recht snijdt.",
    "PSA.107.1": "Looft den HEERE, want Hij is goed; want Zijn goedertierenheid is in der eeuwigheid.",
    "2CO.9.8": "En God is machtig alle genade te doen overvloedig zijn in u; opdat gij in alles te allen tijd, alle genoegzaamheid hebbende, tot alle goed werk overvloedig moogt zijn.",
    "JHN.10.27-28": "Mijn schapen horen Mijn stem, en Ik ken dezelve, en zij volgen Mij. En Ik geef hun het eeuwige leven; en zij zullen niet verloren gaan in der eeuwigheid, en niemand zal dezelve uit Mijn hand rukken.",
    "1CO.10.13": "Ulieden heeft geen verzoeking bevangen dan menselijke; doch God is getrouw, Die u niet zal laten verzocht worden boven hetgeen gij vermoogt; maar Hij zal met de verzoeking ook de uitkomst geven, opdat gij ze kunt verdragen.",
    "MRK.11.24": "Daarom zeg Ik u: Alle dingen, die gij biddende begeert, gelooft, dat gij ze ontvangen zult, en zij zullen u geworden.",
    "GAL.5.13-14": "Want gij zijt tot vrijheid geroepen, broeders, alleenlijk gebruikt de vrijheid niet tot een oorzaak voor het vlees; maar dient elkander door de liefde. Want de gehele wet wordt in een woord vervuld, namelijk in dit: Gij zult uw naaste liefhebben, gelijk uzelven.",
    "ACT.4.12": "En de zaligheid is in geen Anderen; want er is ook onder den hemel geen andere Naam, Die onder de mensen gegeven is, door Welken wij moeten zalig worden.",
    "ISA.41.10": "Vrees niet, want Ik ben met u; zijt niet verbaasd, want Ik ben uw God; Ik sterk u, ook help Ik u, ook ondersteun Ik u met de rechterhand Mijner gerechtigheid.",
    "1JN.4.16": "En wij hebben gekend en geloofd de liefde, die God tot ons heeft. God is liefde; en die in de liefde blijft, blijft in God, en God in hem.",
    "EXO.15.2": "De HEERE is mijn Kracht en Lied, en Hij is mij tot een Heil geweest; deze is mijn God; daarom zal ik Hem een liefelijke woning maken; Hij is mijns vaders God, dies zal ik Hem verheffen!",
    "REV.22.13": "Ik ben de Alfa, en de Omega, het Begin en het Einde; de Eerste en de Laatste.",
    "2TI.4.7-8": "Ik heb den goeden strijd gestreden, ik heb den loop geeindigd, ik heb het geloof behouden; Voorts is mij weggelegd de kroon der rechtvaardigheid, welke mij de Heere, de rechtvaardige Rechter, in dien dag geven zal; en niet alleen mij, maar ook allen, die Zijn verschijning liefgehad hebben.",
    "PSA.121.7-8": "De HEERE zal u bewaren van alle kwaad; uw ziel zal Hij bewaren. De HEERE zal uw uitgang en uw ingang bewaren, van nu aan tot in der eeuwigheid.",
    "ISA.53.5": "Maar Hij is om onze overtredingen verwond, om onze ongerechtigheden is Hij verbrijzeld; de straf, die ons den vrede aanbrengt, was op Hem, en door Zijn striemen is ons genezing geworden.",
    "ROM.10.9-10": "Namelijk, indien gij met uw mond zult belijden den Heere Jezus, en met uw hart geloven, dat God Hem uit de doden opgewekt heeft, zo zult gij zalig worden. Want met het hart gelooft men ter rechtvaardigheid en met den mond belijdt men ter zaligheid.",
    "1PE.2.24": "Die Zelf onze zonden in Zijn lichaam gedragen heeft op het hout; opdat wij, der zonden afgestorven zijnde, der gerechtigheid leven zouden; door Wiens striemen gij genezen zijt.",
    "2PE.1.3": "Gelijk ons Zijn Goddelijke kracht alles, wat tot het leven en de godzaligheid behoort, geschonken heeft, door de kennis Desgenen, Die ons geroepen heeft tot heerlijkheid en deugd;",
    "PSA.94.19": "Als mijn gedachten binnen in mij vermenigvuldigd werden, hebben Uw vertroostingen mijn ziel verkwikt.",
    "MAT.6.34": "Zijt dan niet bezorgd tegen den morgen; want de morgen zal voor het zijne zorgen; elke dag heeft genoeg aan zijn zelfs kwaad.",
    "PHP.4.4": "Verblijdt u in den Heere te allen tijd; wederom zeg ik: Verblijdt u.",
    "EPH.2.8-9": "Want uit genade zijt gij zalig geworden door het geloof; en dat niet uit u, het is Gods gave; Niet uit de werken, opdat niemand roeme.",
    "1PE.5.10": "De God nu aller genade, Die ons geroepen heeft tot Zijn eeuwige heerlijkheid in Christus Jezus, nadat wij een weinig tijds zullen geleden hebben, Dezelve volmake, bevestige, versterke, en fondere ulieden.",
    "ACT.1.8": "Maar gij zult ontvangen de kracht des Heiligen Geestes, Die over u komen zal; en gij zult Mijn getuigen zijn, zo te Jeruzalem, als in geheel Judea en Samaria, en tot aan het uiterste der aarde.",
    "JHN.3.16": "Want alzo lief heeft God de wereld gehad, dat Hij Zijn eniggeboren Zoon gegeven heeft, opdat een iegelijk die in Hem gelooft, niet verderve, maar het eeuwige leven hebbe.",
    "1CH.16.11": "Vraagt naar den HEERE en Zijn sterkte, zoekt Zijn aangezicht geduriglijk.",
    "1TI.4.12": "Niemand verachte uw jonkheid, maar zijt een voorbeeld der gelovigen in woord, in wandel, in liefde, in den geest, in geloof, in reinheid.",
    "EPH.6.10-11": "Voorts, mijn broeders, wordt krachtig in den Heere, en in de sterkte Zijner macht. Doet aan de gehele wapenrusting Gods, opdat gij kunt staan tegen de listige omleidingen des duivels.",
    "JHN.15.12-13": "Dit is Mijn gebod, dat gij elkander liefhebt, gelijkerwijs Ik u liefgehad heb. Niemand heeft meerder liefde dan deze, dat iemand zijn leven zette voor zijn vrienden.",
    "ZEC.4.6": "Toen antwoordde Hij, en sprak tot mij, zeggende: Dit is het woord des HEEREN tot Zerubbabel, zeggende: Niet door kracht noch door geweld, maar door Mijn Geest zal het geschieden, zegt de HEERE der heirscharen.",
    "ROM.8.37": "Maar in dit alles zijn wij meer dan overwinnaars, door Hem, Die ons liefgehad heeft.",
    "PRO.1.7": "De vrees des HEEREN is het beginsel der wetenschap; de dwazen verachten wijsheid en tucht.",
    "PSA.27.14": "Wacht op den HEERE, zijt sterk, en Hij zal uw hart versterken, ja, wacht op den HEERE.",
    "MRK.16.15": "En Hij zeide tot hen: Gaat heen in de gehele wereld, predikt het Evangelie aan alle kreaturen.",
    "JHN.16.33": "Deze dingen heb Ik tot u gesproken, opdat gij in Mij vrede hebt. In de wereld zult gij verdrukking hebben, maar hebt goeden moed, Ik heb de wereld overwonnen.",
    "1PE.4.8": "Maar vooral hebt vurige liefde tot elkander; want de liefde zal menigte van zonden bedekken.",
    "PRO.3.5-6": "Vertrouw op den HEERE met uw ganse hart, en steun op uw verstand niet. Ken Hem in al uw wegen, en Hij zal uw paden recht maken.",
    "ROM.8.31-32": "Wat zullen wij dan tot deze dingen zeggen? Zo God voor ons is, wie zal tegen ons zijn? Die ook Zijn eigen Zoon niet gespaard heeft, maar heeft Hem voor ons allen overgegeven, hoe zal Hij ons ook met Hem niet alle dingen schenken?",
    "HAB.3.19": "De Heere HEERE is mijn Sterkte; en Hij zal mijn voeten maken als der hinden, en Hij zal mij doen treden op mijn hoogten. Voor den opperzangmeester op mijn Neginoth.",
    "MIC.6.8": "Hij heeft u bekend gemaakt, o mens! wat goed is; en wat eist de HEERE van u, dan recht te doen, en weldadigheid lief te hebben, en ootmoediglijk te wandelen met uw God?",
    "MAT.17.20": "En Jezus zeide tot hen: Om uws ongeloofs wil; want voorwaar zeg Ik u: Zo gij een geloof hadt als een mosterdzaad, gij zoudt tot deze berg zeggen: Ga heen van hier derwaarts, en hij zal heengaan; en niets zal u onmogelijk zijn.",
    "MRK.10.45": "Want ook de Zoon des mensen is niet gekomen, om gediend te worden, maar om te dienen, en Zijn ziel te geven tot een rantsoen voor velen.",
    "DAN.12.3": "De leraars nu zullen blinken, als de glans des uitspansels, en die er velen rechtvaardigen, gelijk de sterren, altoos en eeuwiglijk.",
    "PHP.4.6-7": "Weest in geen ding bezorgd; maar laat uw begeerten in alles, door bidden en smeken, met dankzegging bekend worden bij God; En de vrede Gods, die alle verstand te boven gaat, zal uw harten en uw zinnen bewaren in Christus Jezus.",
    "2CO.4.8-9": "Als die in alles verdrukt worden, doch niet benauwd; twijfelmoedig, doch niet mismoedig; Vervolgd, doch niet daarin verlaten; nedergeworpen, doch niet verdorven;",
    "PRO.16.24": "Liefelijke redenen zijn een honigraat, zoet voor de ziel, en medicijn voor het gebeente.",
    "1JN.1.5": "En dit is de verkondiging, die wij van Hem gehoord hebben, en wij u verkondigen, dat God een Licht is, en gans geen duisternis in Hem is.",
    "DEU.6.4-5": "Hoor, Israel! de HEERE, onze God, is een enig HEERE! Zo zult gij den HEERE, uw God, liefhebben, met uw ganse hart, en met uw ganse ziel, en met al uw vermogen.",
    "PSA.23.4": "Al ging ik ook in een dal der schaduw des doods, ik zou geen kwaad vrezen, want Gij zijt met mij; Uw stok en Uw staf, die vertroosten mij.",
    "ROM.8.18": "Want ik houde het daarvoor, dat het lijden dezes tegenwoordigen tijds niet is te waarderen tegen de heerlijkheid, die aan ons zal geopenbaard worden.",
    "REV.3.20": "Zie, Ik sta aan de deur, en Ik klop; indien iemand Mijn stem zal horen, en de deur opendoen, Ik zal tot hem inkomen, en Ik zal met hem avondmaal houden, en hij met Mij.",
    "ISA.30.15": "Want alzo zegt de Heere HEERE, de Heilige Israels: Door wederkering en rust zoudt gijlieden behouden worden, in stilheid en in vertrouwen zou uw sterkte zijn; doch gij hebt niet gewild.",
    "JHN.6.35": "En Jezus zeide tot hen: Ik ben het Brood des levens; die tot Mij komt, zal geenszins hongeren, en die in Mij gelooft, zal nimmermeer dorsten.",
    "ACT.20.35": "Ik heb u in alles getoond, dat men, alzo arbeidende, de zwakken moet opnemen, en gedenken aan de woorden van den Heere Jezus, dat Hij gezegd heeft: Het is zaliger te geven, dan te ontvangen.",
    "JAS.5.16": "Belijdt elkander de misdaden, en bidt voor elkander, opdat gij gezond wordt; een krachtig gebed des rechtvaardigen vermag veel.",
    "ISA.1.18": "Komt dan, en laat ons samen rechten, zegt de HEERE; al waren uw zonden als scharlaken, zij zullen wit worden als sneeuw, al waren zij rood als karmozijn, zij zullen worden als witte wol.",
    "PRO.27.17": "Ijzer scherpt men met ijzer; alzo scherpt een man het aangezicht zijns naasten.",
    "JHN.1.14": "En het Woord is vlees geworden, en heeft onder ons gewoond (en wij hebben Zijn heerlijkheid aanschouwd, een heerlijkheid als des Eniggeborenen van den Vader), vol van genade en waarheid.",
    "1JN.1.9": "Indien wij onze zonden belijden, Hij is getrouw en rechtvaardig, dat Hij ons de zonden vergeve, en ons reinige van alle ongerechtigheid.",
    "MAT.6.33": "Maar zoekt eerst het Koninkrijk Gods en Zijn gerechtigheid, en al deze dingen zullen u toegeworpen worden.",
    "1CO.13.12": "Want wij zien nu door een spiegel in een duistere rede, maar alsdan zullen wij zien aangezicht tot aangezicht; nu ken ik ten dele, maar alsdan zal ik kennen, gelijk ook ik gekend ben.",
    "REV.1.8": "Ik ben de Alfa en de Omega, het Begin en het Einde, zegt de Heere, Die is, en Die was, en Die komen zal, de Almachtige.",
    "PSA.28.7": "De HEERE is mijn Sterkte en mijn Schild; op Hem heeft mijn hart vertrouwd, en ik ben geholpen; dies springt mijn hart van vreugde, en ik zal Hem met mijn gezang loven.",
    "DEU.31.8": "De HEERE nu is Degene, Die voor uw aangezicht gaat; Die zal met u zijn; Hij zal u niet begeven, noch u verlaten; vrees niet, en ontzet u niet.",
    "HEB.4.12": "Want het Woord Gods is levend en krachtig, en scherpsnijdender dan enig tweesnijdend zwaard, en gaat door tot de verdeling der ziel, en des geestes, en der samenvoegselen, en des mergs, en is een oordeler der gedachten en der overleggingen des harten.",
    "MAT.19.14": "Maar Jezus zeide: Laat af van de kinderkens, en verhindert hen niet tot Mij te komen; want derzulken is het Koninkrijk der hemelen.",
    "JAS.4.7-8": "Zo onderwerpt u dan Gode; wederstaat den duivel, en hij zal van u vlieden. Naakt tot God, en Hij zal tot u naken. Reinigt de handen, gij zondaars, en zuivert de harten, gij dubbelhartigen!",
    "PSA.139.13-14": "Want Gij bezit mijn nieren; Gij hebt mij in mijner moeders buik bedekt. Ik loof U, omdat ik op een heel vreselijke wijze wonderbaarlijk gemaakt ben; wonderlijk zijn Uw werken! ook weet het mijn ziel zeer wel.",
    "HOS.6.3": "Dan zullen wij kennen, wij zullen vervolgen, om den HEERE te kennen; Zijn uitgang is bereid als de dageraad; en Hij zal tot ons komen als een regen, als de spade regen en vroege regen des lands.",
    "1CO.10.31": "Hetzij dan dat gijlieden eet, hetzij dat gij drinkt, hetzij dat gij iets anders doet, doet het al ter ere Gods.",
    "JOS.1.8": "Dat het boek dezer wet niet wijke van uw mond, maar overleg het dag en nacht, opdat gij waarneemt te doen naar alles, wat daarin geschreven is; want alsdan zult gij uw wegen voorspoedig maken, en alsdan zult gij verstandelijk handelen.",
    "2CH.7.14": "En Mijn volk, over dewelken Mijn Naam genoemd wordt, zich verootmoedigt en bidt, en zij Mijn aangezicht zoeken, en zich bekeren van hun boze wegen; zo zal Ik uit den hemel horen, en hun zonden vergeven, en hun land genezen.",
    "PSA.19.14": "Laat de redenen mijns monds, en de overdenking mijns harten welbehagelijk zijn voor Uw aangezicht, o HEERE, mijn Rotssteen en mijn Verlosser!",
    "JHN.14.1-3": "Uw hart worde niet ontroerd; gijlieden gelooft in God, gelooft ook in Mij. In het huis Mijns Vaders zijn vele woningen; anderszins zo zou Ik het u gezegd hebben; Ik ga heen om u plaats te bereiden. En zo wanneer Ik heen zal gegaan zijn, en u plaats zal bereid hebben, zo kome Ik weder en zal u tot Mij nemen, opdat gij ook zijn moogt, waar Ik ben.",
    "PSA.147.3": "Hij geneest de gebrokenen van hart, en Hij verbindt hen in hun smarten.",
    "PHP.4.19": "Doch mijn God zal naar Zijn rijkdom vervullen al uw nooddruft, in heerlijkheid, door Christus Jezus.",
    "2CO.13.14": "De genade van den Heere Jezus Christus, en de liefde van God, en de gemeenschap des Heiligen Geestes, zij met u allen. Amen.",
    "1PE.3.15": "Maar heiligt God, den Heere, in uw harten; en zijt altijd bereid tot verantwoording aan een iegelijk, die u rekenschap afeist van de hoop, die in u is, met zachtmoedigheid en vreze.",
    "MAT.25.40": "En de Koning zal antwoorden en tot hen zeggen: Voorwaar zeg Ik u: Voor zoveel gij dit een van deze Mijn minste broeders gedaan hebt, zo hebt gij dat Mij gedaan.",
    "PSA.139.23-24": "Doorgrond mij, o God! en ken mijn hart; beproef mij, en ken mijn gedachten. En zie, of bij mij een schadelijke weg zij; en leid mij op den eeuwigen weg.",
    "JOS.1.9": "Heb Ik het u niet bevolen? wees sterk en heb goeden moed, en verschrik niet, en ontzet u niet; want de HEERE, uw God, is met u alom, waar gij heengaat.",
    "JAS.3.17-18": "Maar de wijsheid, die van boven is, die is ten eerste zuiver, daarna vreedzaam, bescheiden, gezeggelijk, vol van barmhartigheid en van goede vruchten, niet partijdig oordelende, en ongeveinsd. En de vrucht der rechtvaardigheid wordt in vrede gezaaid voor degenen, die vrede maken.",
    "REV.22.17": "En de Geest en de Bruid zeggen: Kom! En die het hoort, zegge: Kom! En die dorst heeft, kome; en die wil, neme het water des levens om niet.",
    "MAT.19.26": "En Jezus, hen aanziende, zeide tot hen: Bij de mensen is dat onmogelijk, maar bij God zijn alle dingen mogelijk.",
    "PSA.103.11-12": "Want zo hoog de hemel is boven de aarde, is Zijn goedertierenheid geweldig over degenen, die Hem vrezen. Zo ver het oosten is van het westen, zo ver doet Hij onze overtredingen van ons.",
    "REV.4.11": "Gij Heere, zijt waardig te ontvangen de heerlijkheid, en de eer, en de kracht; want Gij hebt alle dingen geschapen, en door Uw wil zijn zij, en zijn zij geschapen.",
    "PHP.1.21": "Want het leven is mij Christus, en het sterven is mij gewin.",
    "2TI.3.16-17": "Al de Schrift is van God ingegeven, en is nuttig tot lering, tot wederlegging, tot verbetering, tot onderwijzing, die in de rechtvaardigheid is; Opdat de mens Gods volmaakt zij, tot alle goed werk volmaaktelijk toegerust.",
    "JER.31.3": "De HEERE is mij verschenen van verre tijden! Ja, Ik heb u liefgehad met een eeuwige liefde; daarom heb Ik u getrokken met goedertierenheid.",
    "LUK.15.7": "Ik zeg ulieden, dat er alzo blijdschap zal zijn in den hemel over een zondaar, die zich bekeert, meer dan over negen en negentig rechtvaardigen, die de bekering niet van node hebben.",
    "ISA.54.10": "Want bergen zullen wijken, en heuvelen wankelen; maar Mijn goedertierenheid zal van u niet wijken, en het verbond Mijns vredes zal niet wankelen, zegt de HEERE, uw Ontfermer.",
    "EPH.3.20-21": "Hem nu, Die machtig is meer dan overvloediglijk te doen, boven al wat wij bidden of denken, naar de kracht, die in ons werkt, Hem, zeg ik, zij de heerlijkheid in de Gemeente, door Christus Jezus, in alle geslachten, tot alle eeuwigheid. Amen.",
    "ROM.5.3-5": "En niet alleenlijk dit, maar wij roemen ook in de verdrukkingen, wetende, dat de verdrukking lijdzaamheid werkt; En de lijdzaamheid bevinding, en de bevinding hoop; En de hoop beschaamt niet, omdat de liefde Gods in onze harten uitgestort is door den Heiligen Geest, Die ons is gegeven.",
    "1JN.4.19": "Wij hebben Hem lief, omdat Hij ons eerst liefgehad heeft.",
    "JHN.14.6": "Jezus zeide tot hem: Ik ben de Weg, en de Waarheid, en het Leven. Niemand komt tot den Vader, dan door Mij.",
    "1PE.5.6-7": "Vernedert u dan onder de krachtige hand Gods, opdat Hij u verhoge te Zijner tijd. Werpt al uw bekommernis op Hem, want Hij zorgt voor u.",
    "EST.4.14": "Want indien gij enigszins zwijgen zult te dezer tijd, zo zal den Joden verkwikking en verlossing uit een andere plaats ontstaan; maar gij en uws vaders huis zult omkomen; en wie weet, of gij niet om zulken tijd als deze is, tot dit koninkrijk geraakt zijt.",
    "PSA.51.10": "Schep mij een rein hart, o God! en vernieuw in het binnenste van mij een vasten geest.",
    "LUK.6.37-38": "En oordeelt niet, en gij zult niet geoordeeld worden; verdoemt niet, en gij zult niet verdoemd worden; laat los, en gij zult losgelaten worden. Geeft, en u zal gegeven worden; een goede, neergedrukte, en geschudde en overlopende maat zal men in uw schoot geven; want met dezelfde maat, waarmede gijlieden meet, zal ulieden wedergemeten worden.",
    "PRO.2.6": "Want de HEERE geeft wijsheid; uit Zijn mond komt kennis en verstand.",
    "MAT.7.24-25": "Een iegelijk dan, die deze Mijn woorden hoort en dezelve doet, dien zal Ik vergelijken bij een voorzichtig man, die zijn huis op een steenrots gebouwd heeft; En er is slagregen nedergevallen, en de waterstromen zijn gekomen, en de winden hebben gewaaid, en zijn tegen hetzelve huis aangevallen, en het is niet gevallen, want het was op de steenrots gegrond.",
    "TIT.2.11-13": "Want de zaligmakende genade Gods is verschenen aan alle mensen. En onderwijst ons, dat wij, de goddeloosheid en de wereldse begeerlijkheden verzakende, matig en rechtvaardig, en godzalig leven zouden in deze tegenwoordige wereld; Verwachtende de zalige hoop en verschijning der heerlijkheid van den groten God en onzen Zaligmaker Jezus Christus;",
    "LUK.2.14": "Ere zij God in de hoogste hemelen, en vrede op aarde, in de mensen een welbehagen.",
    "JOB.23.10": "Doch Hij kent den weg, die bij mij is; Hij beproeve mij; als goud zal ik uitkomen.",
    "2CO.9.6-7": "En dit zeg ik: Die spaarzamelijk zaait, zal ook spaarzamelijk maaien; en die in zegeningen zaait, zal ook in zegeningen maaien. Een iegelijk doe, gelijk hij in zijn hart voorneemt; niet uit droefheid, of uit nooddwang; want God heeft een blijmoedigen gever lief.",
    "PRO.19.21": "In het hart des mans zijn veel gedachten; maar de raad des HEEREN, die zal bestaan.",
    "ROM.5.1-2": "Wij dan, gerechtvaardigd zijnde uit het geloof, hebben vrede bij God, door onzen Heere Jezus Christus; Door Welken wij ook de toeleiding hebben door het geloof tot deze genade, in welke wij staan, en roemen in de hoop der heerlijkheid Gods.",
    "LUK.6.27-28": "Maar Ik zeg ulieden, die dit hoort: Hebt uw vijanden lief; doet wel dengenen, die u haten. Zegent degenen, die u vervloeken, en bidt voor degenen, die u geweld doen.",
    "PRO.22.6": "Leer den jongen de eerste beginselen naar den eis zijns wegs; als hij ook oud zal geworden zijn, zal hij daarvan niet afwijken.",
    "NUM.23.19": "God is geen man, dat Hij liegen zou, noch eens mensen kind, dat het Hem berouwen zou; zou Hij het zeggen, en niet doen, of spreken, en niet bestendig maken?",
    "PHP.4.8": "Voorts, broeders, al wat waarachtig is, al wat eerlijk is, al wat rechtvaardig is, al wat rein is, al wat liefelijk is, al wat wel luidt, zo er enige deugd is, en zo er enige lof is, bedenkt datzelve;",
    "COL.2.6-7": "Gelijk gij dan Christus Jezus, den Heere, hebt aangenomen, wandelt alzo in Hem; Geworteld en opgebouwd in Hem, en bevestigd in het geloof, gelijkerwijs gij geleerd zijt, overvloedig zijnde in hetzelve, met dankzegging.",
    "ROM.12.12": "Verblijdt u in de hoop. Zijt geduldig in de verdrukking. Volhardt in het gebed.",
    "PHP.2.3-4": "Doet geen ding door twisting of ijdele eer, maar door ootmoedigheid achte de een den ander uitnemender dan zichzelven. Een iegelijk zie niet op het zijne, maar een iegelijk zie ook op hetgeen der anderen is.",
    "1JN.5.14-15": "En dit is de vrijmoedigheid, die wij tot Hem hebben, dat zo wij iets bidden naar Zijn wil, Hij ons verhoort. En indien wij weten, dat Hij ons verhoort, wat wij ook bidden, zo weten wij, dat wij de beden verkrijgen, die wij van Hem gebeden hebben.",
    "EPH.5.8": "Want gij waart eertijds duisternis, maar nu zijt gij licht in den Heere; wandelt als kinderen des lichts.",
    "1JN.4.7-8": "Geliefden! Laat ons elkander liefhebben, want de liefde is uit God; en een iegelijk, die liefheeft, is uit God geboren, en kent God; Die niet liefheeft, die heeft God niet gekend; want God is liefde.",
    "PSA.103.1-2": "Loof den HEERE, mijn ziel, en al wat binnen in mij is, Zijn heiligen Naam. Loof den HEERE, mijn ziel, en vergeet geen van Zijn weldaden;",
    "HOS.6.6": "Want Ik heb lust tot weldadigheid, en niet tot offer; en tot de kennis Gods, meer dan tot brandofferen.",
    "ROM.8.1": "Zo is er dan nu geen verdoemenis voor degenen, die in Christus Jezus zijn, die niet naar het vlees wandelen, maar naar den Geest.",
    "ISA.60.1": "Maak u op, word verlicht, want uw Licht komt, en de heerlijkheid des HEEREN gaat over u op.",
    "1TH.5.23-24": "En de God des vredes Zelf heilige u geheel en al; en uw geheel oprechte geest, en ziel, en lichaam worde onberispelijk bewaard in de toekomst van onzen Heere Jezus Christus. Hij, Die u roept, is getrouw, Die het ook doen zal.",
    "1CO.6.19-20": "Of weet gij niet, dat ulieder lichaam een tempel is van den Heiligen Geest, Die in u is, Dien gij van God hebt, en dat gij uws zelfs niet zijt? Want gij zijt duur gekocht: zo verheerlijkt dan God in uw lichaam en in uw geest, welke Godes zijn.",
    "GEN.28.15": "En zie, Ik ben met u, en Ik zal u behoeden overal, waarheen gij trekken zult, en Ik zal u wederbrengen in dit land; want Ik zal u niet verlaten, totdat Ik zal gedaan hebben, hetgeen Ik tot u gesproken heb.",
    "PSA.73.26": "Bezwijkt mijn vlees en mijn hart, zo is God de Rotssteen mijns harten, en mijn Deel in eeuwigheid.",
    "SNG.8.7": "Vele wateren zouden deze liefde niet kunnen uitblussen; ja, de rivieren zouden ze niet verdrinken; al gaf iemand al het goed van zijn huis voor deze liefde, men zou hem te enenmale verachten.",
    "JER.32.17": "Ach, Heere HEERE! Zie, Gij hebt de hemelen en de aarde gemaakt, door Uw grote kracht en door Uw uitgestrekten arm; geen ding is U te wonderlijk.",
    "1CH.16.34": "Looft den HEERE, want Hij is goed, want Zijn goedertierenheid is tot in eeuwigheid.",
    "GAL.5.1": "Staat dan in de vrijheid, met welke ons Christus vrijgemaakt heeft, en wordt niet wederom met het juk der dienstbaarheid bevangen.",
    "PSA.34.18": "De HEERE is nabij de gebrokenen van harte, en Hij behoudt de verslagenen van geest.",
    "DAN.3.17-18": "Zal het zo zijn, onze God, Dien wij eren, is machtig ons te verlossen uit den oven des brandenden vuurs, en Hij zal ons uit uw hand, o koning! verlossen. Maar zo niet, u zij bekend, o koning! dat wij uw goden niet zullen eren, noch het gouden beeld, dat gij hebt opgericht, zullen aanbidden.",
    "1TI.1.17": "Den Koning nu der eeuwen, den onverderfelijken, den onzienlijken, den alleen wijzen God, zij eer en heerlijkheid in alle eeuwigheid. Amen.",
    "PSA.86.5": "Want Gij, HEERE! zijt goed, en gaarne vergevende, en van grote goedertierenheid allen, die U aanroepen.",
    "AMO.5.24": "Maar laat het oordeel zich daarhenen wenden als de wateren, en de gerechtigheid als een sterke beek.",
    "JAS.1.17": "Alle goede gave, en alle volmaakte gifte is van boven, van den Vader der lichten afkomende, bij Welken geen verandering is, of schaduw van omkering.",
    "JUD.1.24-25": "Hem nu, Die machtig is u van struikelen te bewaren, en onstraffelijk te stellen voor Zijn heerlijkheid, in vreugde, Den alleen wijzen God, onzen Zaligmaker, zij heerlijkheid en majesteit, kracht en macht, beide nu en in alle eeuwigheid. Amen.",
    "2PE.3.9": "De Heere vertraagt de belofte niet (gelijk enigen dat traagheid achten), maar is lankmoedig over ons, niet willende, dat enigen verloren gaan, maar dat zij allen tot bekering komen.",
    "ISA.9.6": "Want een Kind is ons geboren, een Zoon is ons gegeven, en de heerschappij is op Zijn schouder; en men noemt Zijn naam Wonderlijk, Raad, Sterke God, Vader der eeuwigheid, Vredevorst;",
    "LUK.2.10-11": "En de engel zeide tot hen: Vreest niet, want, ziet, ik verkondig u grote blijdschap, die al den volke wezen zal; Namelijk dat u heden geboren is de Zaligmaker, welke is Christus, de Heere, in de stad Davids.",
    "1TI.6.6-8": "Doch de godzaligheid is een groot gewin met vergenoeging. Want wij hebben niets in de wereld gebracht, het is openbaar, dat wij ook niet kunnen iets daaruit dragen. Maar als wij voedsel en deksel hebben, wij zullen daarmede vergenoegd zijn.",
    "NAM.1.7": "De HEERE is goed, Hij is ter sterkte in den dag der benauwdheid, en Hij kent hen, die op Hem betrouwen.",
    "PSA.27.1": "De HEERE is mijn Licht en mijn Heil, voor wien zou ik vrezen? De HEERE is mijns levens kracht, voor wien zou ik vervaard zijn?",
    "COL.1.15-17": "Dewelke het Beeld is des onzienlijken Gods, de Eerstgeborene aller kreaturen. Want door Hem zijn alle dingen geschapen, die in de hemelen en die op de aarde zijn, die zienlijk en die onzienlijk zijn, hetzij tronen, hetzij heerschappijen, hetzij overheden, hetzij machten; alle dingen zijn door Hem en tot Hem geschapen; En Hij is voor alle dingen, en alle dingen bestaan te zamen door Hem;",
    "ZEP.3.17": "De HEERE uw God, is in het midden van u, een Held, Die verlossen zal; Hij zal over u vrolijk zijn met blijdschap, Hij zal zwijgen in Zijn liefde, Hij zal Zich over u verheugen met gejuich.",
    "PSA.90.12": "Leer ons alzo onze dagen tellen, dat wij een wijs hart bekomen.",
    "ROM.8.24-25": "Want wij zijn in hope zalig geworden. De hoop nu, die gezien wordt, is geen hoop; want hetgeen iemand ziet, waarom zal hij het ook hopen? Maar indien wij hopen, hetgeen wij niet zien, zo verwachten wij het met lijdzaamheid.",
    "PSA.39.7": "En nu, wat verwacht ik, o HEERE! Mijn hoop, die is op U.",
    "LAM.3.21-23": "Dit zal ik mij ter harte nemen, daarom zal ik hopen; Het zijn de goedertierenheden des HEEREN, dat wij niet vernield zijn, dat Zijn barmhartigheden geen einde hebben; Zij zijn allen morgen nieuw, Uw trouw is groot.",
    "PSA.71.5": "Want Gij zijt mijn Verwachting, Heere, HEERE! mijn Vertrouwen van mijn jeugd aan.",
    "HEB.6.19": "Welke wij hebben als een anker der ziel, hetwelk zeker en vast is, en ingaat in het binnenste van het voorhangsel;",
    "PSA.130.5": "Ik verwacht den HEERE; mijn ziel verwacht, en ik hoop op Zijn Woord.",
    "PRO.23.18": "Want zekerlijk, er is een beloning; en uw verwachting zal niet afgesneden worden.",
    "PSA.42.11": "Wat buigt gij u neder, o mijn ziel! en wat zijt gij onrustig in mij? Hoop op God, want ik zal Hem nog loven; Hij is de menigvuldige Verlossing mijns aangezichts, en mijn God.",
    "TIT.2.13": "Verwachtende de zalige hoop en verschijning der heerlijkheid van den groten God en onzen Zaligmaker Jezus Christus;",
    "HEB.10.23": "Laat ons de onwankelbare belijdenis der hoop vast houden; (want Die het beloofd heeft, is getrouw);",
    "PSA.33.22": "Uw goedertierenheid, HEERE! zij over ons; gelijk als wij op U hopen.",
    "1PE.1.13": "Daarom opschortende de lenden uws verstands, en nuchteren zijnde, hoopt volkomenlijk op de genade, die u toegebracht wordt in de openbaring van Jezus Christus.",
    "PSA.31.24": "Zijt sterk, en Hij zal ulieder hart versterken, allen gij, die op den HEERE hoopt!",
    "COL.1.27": "Aan wie God heeft willen bekend maken, welke zij de rijkdom der heerlijkheid dezer verborgenheid onder de heidenen, welke is Christus onder u, de Hoop der heerlijkheid;",
    "PSA.62.5": "Doch gij, o mijn ziel! zwijg Gode; want van Hem is mijn verwachting.",
    "PSA.147.11": "De HEERE heeft een welgevallen aan hen, die Hem vrezen, die op Zijn goedertierenheid hopen.",
    "1TH.4.13-14": "Doch, broeders, ik wil niet, dat gij onwetende zijt van degenen, die ontslapen zijn, opdat gij niet bedroefd zijt, gelijk als de anderen, die geen hoop hebben. Want indien wij geloven, dat Jezus gestorven is en opgestaan, alzo zal ook God degenen, die ontslapen zijn in Jezus, weder brengen met Hem.",
    "PRO.13.12": "De uitgestelde hoop krenkt het hart; maar de begeerte, die komt, is een boom des levens.",
    "PSA.119.114": "Gij zijt mijn Schuilplaats en mijn Schild; op Uw Woord heb ik gehoopt.",
    "2CO.4.17-18": "Want onze lichte verdrukking, die zeer haast voorbij gaat, werkt ons een gans zeer uitnemend eeuwig gewicht der heerlijkheid; Dewijl wij niet aanmerken de dingen, die men ziet, maar de dingen, die men niet ziet; want de dingen, die men ziet, zijn tijdelijk, maar de dingen, die men niet ziet, zijn eeuwig.",
    "ISA.26.3-4": "Het is een bevestigd voornemen, Gij zult allerlei vrede bewaren, want men heeft op U vertrouwd. Vertrouwt op den HEERE tot in der eeuwigheid; want in den Heere HEERE is een eeuwige rotssteen.",
    "PSA.37.5": "Wentel uw weg op den HEERE, en vertrouw op Hem; Hij zal het maken;",
    "PSA.9.10": "En die Uw Naam kennen, zullen op U vertrouwen, omdat Gij, HEERE, niet hebt verlaten degenen, die U zoeken.",
    "PSA.20.7": "Dezen vermelden van wagens, en die van paarden; maar wij zullen vermelden van den Naam des HEEREN, onzes Gods.",
    "PSA.62.8": "Vertrouw op Hem te aller tijd, o gij volk! Stort ulieder hart uit voor Zijn aangezicht; God is ons een Toevlucht. Sela.",
    "PSA.112.7": "Hij zal voor geen kwaad gerucht vrezen; zijn hart is vast, betrouwende op den HEERE.",
    "PSA.118.8": "Het is beter tot den HEERE toevlucht te nemen, dan op den mens te vertrouwen.",
    "ISA.12.2": "Ziet, God is mijn Heil, ik zal vertrouwen en niet vrezen; want de Heere HEERE is mijn Sterkte en mijn Psalm, en Hij is mij tot Heil geworden.",
    "PSA.125.1": "Die op den HEERE vertrouwen, zijn als de berg Sion, die niet wankelt, maar blijft in eeuwigheid.",
    "PSA.143.8": "Doe mij Uw goedertierenheid in den morgenstond horen, want ik betrouw op U; maak mij bekend den weg, dien ik te gaan heb, want ik hef mijn ziel tot U op.",
    "PRO.29.25": "De siddering des mensen legt een strik; maar die op den HEERE vertrouwt, zal in een hoog vertrek gesteld worden.",
    "PSA.91.2": "Ik zal tot den HEERE zeggen: Mijn Toevlucht en mijn Burg! mijn God, op Welken ik vertrouw!",
    "2CO.5.7": "(Want wij wandelen door geloof en niet door aanschouwen.)",
    "PSA.40.4": "Welgelukzalig is de man, die den HEERE tot zijn vertrouwen stelt, en niet omziet naar de hovaardigen, en die tot leugen afwijken.",
    "PSA.13.5-6": "Maar ik vertrouw op Uw goedertierenheid; mijn hart zal zich verheugen in Uw heil; ik zal den HEERE zingen, omdat Hij aan mij welgedaan heeft.",
    "PSA.84.12": "HEERE der heirscharen! welgelukzalig is de mens, die op U vertrouwt.",
    "PRO.16.20": "Die op het woord verstandelijk let, zal het goede vinden; en die op den HEERE vertrouwt, is welgelukzalig.",
    "PSA.32.10": "De goddeloze heeft veel smarten, maar die op den HEERE vertrouwt, dien zal de goedertierenheid omringen.",
    "ISA.50.10": "Wie is er onder ulieden, die den HEERE vreest, die naar de stem Zijns Knechts hoort? Als hij in de duisternissen wandelt, en geen licht heeft, dat hij betrouwe op den Naam des HEEREN, en steune op zijn God.",
    "PSA.37.3": "Vertrouw op den HEERE, en doe het goede; bewoon de aarde, en voed u met getrouwigheid.",
    "PSA.115.11": "Gijlieden, die den HEERE vreest! vertrouwt op den HEERE; Hij is hun Hulp en hun Schild.",
    "ROM.4.20-21": "En hij heeft aan de beloftenis Gods niet getwijfeld door ongeloof; maar is gesterkt geweest in het geloof, gevende God de eer; En ten volle verzekerd zijnde, dat hetgeen beloofd was, Hij ook machtig was te doen.",
    "1JN.4.18-19": "Er is in de liefde geen vrees, maar de volmaakte liefde drijft de vrees buiten; want de vrees heeft pijn, en die vreest, is niet volmaakt in de liefde. Wij hebben Hem lief, omdat Hij ons eerst liefgehad heeft.",
    "1JN.3.18": "Mijn kinderkens, laat ons niet liefhebben met den woorde, noch met de tong, maar met de daad en waarheid.",
    "COL.3.14": "En boven dit alles doet aan de liefde, dewelke is de band der volmaaktheid.",
    "ROM.13.10": "De liefde doet den naaste geen kwaad. Zo is dan de liefde de vervulling der wet.",
    "DEU.6.5": "Zo zult gij den HEERE, uw God, liefhebben, met uw ganse hart, en met uw ganse ziel, en met al uw vermogen.",
    "1CO.16.14": "Dat al uw dingen in de liefde geschieden.",
    "EPH.5.2": "En wandelt in de liefde, gelijkerwijs ook Christus ons liefgehad heeft, en Zichzelven voor ons heeft overgegeven tot een offerande en een slachtoffer, Gode tot een welriekenden reuk.",
    "GAL.5.13": "Want gij zijt tot vrijheid geroepen, broeders, alleenlijk gebruikt de vrijheid niet tot een oorzaak voor het vlees; maar dient elkander door de liefde.",
    "PSA.136.26": "Looft den God des hemels; want Zijn goedertierenheid is in der eeuwigheid.",
    "LUK.6.35": "Maar hebt uw vijanden lief, en doet goed, en leent, zonder iets weder te hopen; en uw loon zal groot zijn, en gij zult kinderen des Allerhoogsten zijn; want Hij is goedertieren over de ondankbaren en bozen.",
    "ROM.12.9-10": "De liefde zij ongeveinsd. Hebt een afkeer van het boze, en hangt het goede aan. Hebt elkander hartelijk lief met broederlijke liefde; met eer de een de ander voorgaande.",
    "1JN.4.10-11": "Hierin is de liefde, niet dat wij God liefgehad hebben, maar dat Hij ons lief heeft gehad, en Zijn Zoon gezonden heeft tot een verzoening voor onze zonden. Geliefden, indien God ons alzo lief heeft gehad, zo zijn ook wij schuldig elkander lief te hebben.",
    "EPH.4.2": "Met alle ootmoedigheid en zachtmoedigheid, met lankmoedigheid, verdragende elkander in liefde;",
    "PSA.86.15": "Maar Gij, Heere! zijt een barmhartig en genadig God, lankmoedig, en groot van goedertierenheid en waarheid.",
    "EXO.20.12": "Eert uw vader en uw moeder, opdat uw dagen verlengd worden in het land, dat u de HEERE uw God geeft.",
    "PSA.127.3-5": "Ziet, de kinderen zijn een erfdeel des HEEREN; des buiks vrucht is een beloning. Gelijk de pijlen zijn in de hand eens helds, zodanig zijn de zonen der jeugd. Welgelukzalig is de man, die zijn pijlkoker met dezelve gevuld heeft; zij zullen niet beschaamd worden, als zij met de vijanden spreken zullen in de poort.",
    "EPH.6.1-3": "Gij kinderen, zijt uw ouderen gehoorzaam in den Heere; want dat is recht. Eert uw vader en moeder (hetwelk het eerste gebod is met een belofte), Opdat het u welga, en dat gij lang leeft op de aarde.",
    "COL.3.20-21": "Gij kinderen, zijt uw ouderen gehoorzaam in alles, want dat is de Heere welbehagelijk. Gij vaders, tergt uw kinderen niet, opdat zij niet moedeloos worden.",
    "PRO.17.6": "De kroon de ouden zijn de kindskinderen, en der kinderen sieraad zijn hun vaderen.",
    "PSA.103.17": "Maar de goedertierenheid des HEEREN is van eeuwigheid en tot eeuwigheid over degenen, die Hem vrezen, en Zijn gerechtigheid aan kindskinderen;",
    "DEU.6.6-7": "En deze woorden, die ik u heden gebiede, zullen in uw hart zijn. En gij zult ze uw kinderen inscherpen, en daarvan spreken, als gij in uw huis zit, en als gij op den weg gaat, en als gij nederligt, en als gij opstaat.",
    "GEN.2.24": "Daarom zal de man zijn vader en zijn moeder verlaten, en zijn vrouw aankleven; en zij zullen tot een vlees zijn.",
    "PRO.31.28-29": "Haar kinderen staan op, en roemen haar welgelukzalig; ook haar man, en hij prijst haar, zeggende: Vele dochteren hebben deugdelijke gehandeld; maar gij gaat die allen te boven.",
    "EPH.5.25": "Gij mannen, hebt uw eigen vrouwen lief, gelijk ook Christus de Gemeente liefgehad heeft, en Zichzelven voor haar heeft overgegeven;",
    "1TI.5.8": "Doch zo iemand de zijnen, en voornamelijk zijn huisgenoten, niet verzorgt, die heeft het geloof verloochend, en is erger dan een ongelovige.",
    "PSA.128.3": "Uw huisvrouw zal wezen als een vruchtbare wijnstok aan de zijden van uw huis; uw kinderen als olijfplanten rondom uw tafel.",
    "PRO.1.8-9": "Mijn zoon! hoor de tucht uws vaders, en verlaat de leer uwer moeder niet; Want zij zullen uw hoofd een aangenaam toevoegsel zijn, en ketenen aan uw hals.",
    "PSA.133.1": "Ziet, hoe goed en hoe liefelijk is het, dat broeders ook samenwonen.",
    "PRO.20.7": "De rechtvaardige wandelt steeds in zijn oprechtheid; welgelukzalig zijn zijn kinderen na hem.",
    "ISA.54.13": "En al uw kinderen zullen van den HEERE geleerd zijn, en de vrede uwer kinderen zal groot zijn.",
    "MAL.4.6": "En hij zal het hart der vaderen tot de kinderen wederbrengen, en het hart der kinderen tot hun vaderen; opdat Ik niet kome, en de aarde met den ban sla.",
    "PRO.15.20": "Een wijs zoon zal den vader verblijden; maar een zot mens veracht zijn moeder.",
    "EPH.5.33": "Zo dan ook gijlieden, elk in het bijzonder, een iegelijk hebbe zijn eigen vrouw, alzo lief als zichzelven; en de vrouw zie, dat zij den man vreze.",
    "PRO.23.24-25": "De vader des rechtvaardigen zal zich zeer verheugen; en die een wijzen zoon gewint, zal zich over hem verblijden. Laat uw vader zich verblijden, ook uw moeder; en laat haar zich verheugen, die u gebaard heeft.",
    "GEN.18.19": "Want Ik heb hem gekend, opdat hij zijn kinderen en zijn huis na hem zoude bevelen, en zij den weg des HEEREN houden, om te doen gerechtigheid en gerichte; opdat de HEERE over Abraham brenge, hetgeen Hij over hem gesproken heeft.",
    "PSA.68.6": "Een God, Die de eenzamen zet in een huisgezin, uitvoert, die in boeien gevangen zijn; maar de afvalligen wonen in het dorre.",
    "PRO.18.22": "Die een vrouw gevonden heeft, heeft een goede zaak gevonden, en hij heeft welgevallen getrokken van den HEERE.",
    "COL.3.18-19": "Gij vrouwen, zijt uw eigen mannen onderdanig, gelijk het betaamt in den Heere. Gij mannen, hebt uw vrouwen lief, en wordt niet verbitterd tegen haar.",
    "PRO.6.20": "Mijn zoon, bewaar het gebod uws vaders, en verlaat de wet uwer moeder niet.",
    "PRO.31.10": "Wie zal een deugdelijke huisvrouw vinden? Want haar waardij is verre boven de robijnen.",
    "ROM.5.1": "Wij dan, gerechtvaardigd zijnde uit het geloof, hebben vrede bij God, door onzen Heere Jezus Christus;",
    "COL.3.15": "En de vrede Gods heerse in uw harten, tot welken gij ook geroepen zijt in een lichaam; en weest dankbaar.",
    "PSA.29.11": "De HEERE zal Zijn volk sterkte geven; de HEERE zal Zijn volk zegenen met vrede.",
    "MAT.5.9": "Zalig zijn de vreedzamen; want zij zullen Gods kinderen genaamd worden.",
    "ROM.12.18": "Indien het mogelijk is, zoveel in u is, houdt vrede met alle mensen.",
    "PSA.34.14": "Wijk af van het kwaad, en doe het goede; zoek den vrede, en jaag dien na.",
    "PRO.16.7": "Als iemands wegen den HEERE behagen, zo zal Hij ook zijn vijanden met hem bevredigen.",
    "ISA.32.17": "En het werk der gerechtigheid zal vrede zijn; en de werking der gerechtigheid zal zijn gerustheid en zekerheid tot in eeuwigheid.",
    "PSA.119.165": "Die Uw wet beminnen, hebben groten vrede, en zij hebben geen aanstoot.",
    "ROM.14.17": "Want het Koninkrijk Gods is niet spijs en drank, maar rechtvaardigheid, en vrede, en blijdschap, door den Heiligen Geest.",
    "EPH.2.14": "Want Hij is onze vrede, Die deze beiden een gemaakt heeft, en den middelmuur des afscheidsels gebroken hebbende,",
    "PSA.85.8": "Ik zal horen, wat God, de HEERE, spreken zal; want Hij zal tot Zijn volk en tot Zijn gunstgenoten van vrede spreken; maar dat zij niet weder tot dwaasheid keren.",
    "JAS.3.18": "En de vrucht der rechtvaardigheid wordt in vrede gezaaid voor degenen, die vrede maken.",
    "HEB.12.14": "Jaagt den vrede na met allen, en de heiligmaking, zonder welke niemand den Heere zien zal;",
    "ISA.55.12": "Want in blijdschap zult gijlieden uittrekken, en met vrede voortgeleid worden; de bergen en heuvelen zullen geschal maken met vrolijk gezang voor uw aangezicht, en alle bomen des velds zullen de handen samenklappen.",
    "PSA.37.11": "De zachtmoedigen daarentegen zullen de aarde erfelijk bezitten, en zich verlustigen over groten vrede.",
    "1PE.3.11": "Die wijke af van het kwade, en doe het goede; die zoeke vrede en jage denzelven na.",
    "ROM.8.6": "Want het bedenken des vleses is de dood; maar het bedenken des Geestes is het leven en vrede;",
    "PSA.122.6-7": "Bidt om den vrede van Jeruzalem; wel moeten zij varen, die u beminnen. Vrede zij in uw vesting, welvaren in uw paleizen.",
    "ISA.48.18": "Och, dat gij naar Mijn geboden geluisterd hadt! zo zou uw vrede geweest zijn als een rivier, en uw gerechtigheid als de golven der zee.",
    "ISA.40.29": "Hij geeft den moeden kracht, en Hij vermenigvuldigt de sterkte dien, die geen krachten heeft.",
    "PSA.46.1-2": "God is ons een Toevlucht en Sterkte; Hij is krachtelijk bevonden een Hulp in benauwdheden. Daarom zullen wij niet vrezen, al veranderde de aarde haar plaats, en al werden de bergen verzet in het hart der zeeen;",
    "EPH.6.10": "Voorts, mijn broeders, wordt krachtig in den Heere, en in de sterkte Zijner macht.",
    "2CO.12.9-10": "En Hij heeft tot mij gezegd: Mijn genade is u genoeg; want Mijn kracht wordt in zwakheid volbracht. Zo zal ik dan veel liever roemen in mijn zwakheden, opdat de kracht van Christus in mij wone. Daarom heb ik een welbehagen in zwakheden, in smaadheden, in noden, in vervolgingen, in benauwdheden, om Christus' wil; want als ik zwak ben, dan ben ik machtig.",
    "1CO.16.13": "Waakt, staat in het geloof, houdt u mannelijk, zijt sterk.",
    "PSA.118.14": "De HEERE is mijn Sterkte en Psalm, want Hij is mij tot heil geweest.",
    "PSA.138.3": "Ten dage, als ik riep, zo hebt Gij mij verhoord; Gij hebt mij versterkt met kracht in mijn ziel.",
    "PSA.105.4": "Vraagt naar den HEERE en Zijn sterkte; zoekt Zijn aangezicht geduriglijk.",
    "PSA.119.28": "Mijn ziel druipt weg van treurigheid; richt mij op naar Uw woord.",
    "2SA.22.33": "God is mijn Sterkte en Kracht; en Hij heeft mijn weg volkomen geopend.",
    "PSA.59.17": "Van U, o mijn Sterkte! zal ik psalmzingen; want God is mijn Hoog Vertrek, de God mijner goedertierenheid.",
    "EPH.3.16": "Opdat Hij u geve, naar den rijkdom Zijner heerlijkheid, met kracht versterkt te worden door Zijn Geest in den inwendigen mens;",
    "ISA.66.13": "Als een, dien zijn moeder troost, alzo zal Ik u troosten; ja, gij zult te Jeruzalem getroost worden.",
    "MAT.5.4": "Zalig zijn die treuren; want zij zullen vertroost worden.",
    "PSA.119.50": "Dit is mijn troost in mijn ellende, want Uw toezegging heeft mij levend gemaakt.",
    "ISA.40.1": "Troost, troost Mijn volk, zal ulieder God zeggen.",
    "1PE.5.7": "Werpt al uw bekommernis op Hem, want Hij zorgt voor u.",
    "ISA.49.13": "Juicht, gij hemelen! en verheug u, gij aarde! en gij bergen! maakt gedreun met gejuich; want de HEERE heeft Zijn volk vertroost, en Hij zal Zich over Zijn ellendigen ontfermen.",
    "PSA.119.76": "Laat toch Uw goedertierenheid zijn om mij te troosten, naar Uw toezegging aan Uw knecht.",
    "ISA.51.12": "Ik, Ik ben het, Die u troost; wie zijt gij, dat gij vreest voor den mens, die sterven zal? en voor eens mensen kind, dat hooi worden zal?",
    "PSA.9.9": "En de HEERE zal een Hoog Vertrek zijn voor de verdrukte, een Hoog Vertrek in tijden van benauwdheid.",
    "JHN.14.18": "Ik zal u geen wezen laten; Ik kom weder tot u.",
    "PSA.71.21": "Gij zult mijn grootheid vermeerderen, en mij rondom vertroosten.",
    "2TH.2.16-17": "En onze Heere Jezus Christus Zelf, en onze God en Vader, Die ons heeft liefgehad, en gegeven heeft een eeuwige vertroosting en goede hoop in genade, Vertrooste uw harten, en versterke u in alle goed woord en werk.",
    "PSA.138.7": "Als ik wandel in het midden der benauwdheid, maakt Gij mij levend; Uw hand strekt Gij uit tegen den toorn mijner vijanden, en Uw rechterhand behoudt mij.",
    "ISA.61.1-3": "De Geest des Heeren HEEREN is op Mij, omdat de Heere Mij gezalfd heeft, om een blijde boodschap te brengen den zachtmoedigen; Hij heeft Mij gezonden om te verbinden de gebrokenen van harte, om den gevangenen vrijheid uit te roepen, en den gebondenen opening der gevangenis; Om uit te roepen het jaar van het welbehagen des HEEREN, en den dag der wraak onzes Gods; om alle treurigen te troosten; Om den treurigen Sions te beschikken dat hun gegeven worde sieraad voor as, vreugdeolie voor treurigheid, het gewaad des lofs voor een benauwden geest; opdat zij genaamd worden eikebomen der gerechtigheid, een planting des HEEREN, opdat Hij verheerlijkt worde.",
    "PRO.3.13-14": "Welgelukzalig is de mens, die wijsheid vindt, en de mens, die verstandigheid voortbrengt! Want haar koophandel is beter dan de koophandel van zilver, en haar inkomst dan het uitgegraven goud.",
    "PRO.9.10": "De vreze des HEEREN is het beginsel der wijsheid, en de wetenschap der heiligen is verstand.",
    "PSA.111.10": "De vreze des HEEREN is het beginsel der wijsheid; allen, die ze doen, hebben goed verstand; Zijn lof bestaat tot in der eeuwigheid.",
    "PRO.4.7": "De wijsheid is het voornaamste; verkrijg dan wijsheid, en verkrijg verstand met al uw bezitting.",
    "ECC.7.12": "Want de wijsheid is tot een schaduw, en het geld is tot een schaduw; maar de uitnemendheid der wetenschap is, dat de wijsheid haar bezitters het leven geeft.",
    "PRO.16.16": "Hoeveel beter is het wijsheid te bekomen, dan uitgegraven goud, en uitnemender, verstand te bekomen, dan zilver!",
    "JAS.3.17": "Maar de wijsheid, die van boven is, die is ten eerste zuiver, daarna vreedzaam, bescheiden, gezeggelijk, vol van barmhartigheid en van goede vruchten, niet partijdig oordelende, en ongeveinsd.",
    "PRO.11.2": "Als de hovaardigheid komt, zal de schande ook komen; maar met de ootmoedigen is wijsheid.",
    "PRO.12.15": "De weg des dwazen is recht in zijn ogen; maar die naar raad hoort, is wijs.",
    "PRO.19.20": "Hoor raad, en ontvang tucht, opdat gij in uw laatste wijs zijt.",
    "EPH.5.15-16": "Ziet dan, hoe gij voorzichtiglijk wandelt, niet als onwijzen, maar als wijzen. Den tijd uitkopende, dewijl de dagen boos zijn.",
    "PRO.15.22": "De gedachten worden vernietigd, als er geen raad is; maar door veelheid der raadslieden zal elkeen bestaan.",
    "PRO.13.20": "Die met de wijzen omgaat, zal wijs worden; maar die der zotten metgezel is, zal verbroken worden.",
    "1CO.1.25": "Want het dwaze Gods is wijzer dan de mensen; en het zwakke Gods is sterker dan de mensen.",
    "PRO.18.15": "Het hart der verstandigen bekomt wetenschap, en het oor der wijzen zoekt wetenschap.",
    "PRO.24.3-4": "Door wijsheid wordt een huis gebouwd, en door verstandigheid bevestigd; En door wetenschap worden de binnenkameren vervuld met alle kostelijk en liefelijk goed.",
    "COL.2.2-3": "Opdat hun harten vertroost mogen worden, en zij samengevoegd zijn in de liefde, en dat tot allen rijkdom der volle verzekerdheid des verstands, tot kennis der verborgenheid van God en den Vader, en van Christus; In Denwelken al de schatten der wijsheid en der kennis verborgen zijn.",
    "PRO.3.7": "Zijt niet wijs in uw ogen; vrees den HEERE, en wijk van het kwade.",
    "PSA.119.98-100": "Zij maakt mij door Uw geboden wijzer, dan mijn vijanden zijn, want zij is in eeuwigheid bij mij. Ik ben verstandiger dan al mijn leraars, omdat Uw getuigenissen mijn betrachting zijn. Ik ben voorzichtiger dan de ouden, omdat ik Uw bevelen bewaard heb.",
    "PRO.17.27-28": "Wie wetenschap weet, houdt zijn woorden in; en een man van verstand is kostelijk van geest. Een dwaas zelfs, die zwijgt, zal wijs geacht worden, en die zijn lippen toesluit, verstandig.",
    "DAN.2.20-21": "Daniel antwoordde en zeide: De Naam Gods zij geloofd van eeuwigheid tot in eeuwigheid, want Zijn is de wijsheid en de kracht. Want Hij verandert de tijden en stonden; Hij zet de koningen af, en Hij bevestigt de koningen; Hij geeft den wijzen wijsheid, en wetenschap dengenen, die verstand hebben;",
    "PRO.14.29": "De lankmoedige is groot van verstand; maar die haastig is van gemoed, verheft de dwaasheid.",
    "JOB.28.28": "Maar tot den mens heeft Hij gezegd: Zie, de vreze des HEEREN is de wijsheid, en van het kwade te wijken is het verstand.",
    "EPH.5.20": "Dankende te allen tijd over alle dingen God en den Vader, in den Naam van onzen Heere Jezus Christus;",
    "PHP.4.6": "Weest in geen ding bezorgd; maar laat uw begeerten in alles, door bidden en smeken, met dankzegging bekend worden bij God;",
    "PSA.95.1-2": "Komt, laat ons den HEERE vrolijk zingen; laat ons juichen den Rotssteen onzes heils. Laat ons Zijn aangezicht tegemoet gaan met lof; laat ons Hem juichen met psalmen.",
    "PSA.9.1": "Ik zal den HEERE loven met mijn ganse hart; ik zal al Uw wonderen vertellen.",
    "HEB.13.15": "Laat ons dan door Hem altijd Gode opofferen een offerande des lofs, dat is, de vrucht der lippen, die Zijn Naam belijden.",
    "PSA.69.30": "Ik zal Gods Naam prijzen met gezang, en Hem met dankzegging grootmaken.",
    "2CO.9.15": "Doch Gode zij dank voor Zijn onuitsprekelijke gave.",
    "PSA.106.1": "Hallelujah! Looft den HEERE, want Hij is goed, want Zijn goedertierenheid is in der eeuwigheid.",
    "PSA.92.1-2": "Het is goed, dat men den HEERE love, en Uw Naam psalmzinge, o Allerhoogste! Dat men in den morgenstond Uw goedertierenheid verkondige, en Uw getrouwheid in de nachten;",
    "1TI.4.4-5": "Want alle schepsel Gods is goed, en er is niets verwerpelijk, met dankzegging genomen zijnde; Want het wordt geheiligd door het Woord van God, en door het gebed.",
    "PSA.34.1": "Ik zal den HEERE loven te aller tijd; Zijn lof zal geduriglijk in mijn mond zijn.",
    "DAN.2.23": "Ik dank en ik loof U, o God mijner vaderen! omdat Gij mij wijsheid en kracht gegeven hebt, en mij nu bekend gemaakt hebt, wat wij van U verzocht hebben, want Gij hebt ons des konings zaak bekend gemaakt.",
    "COL.4.2": "Houdt sterk aan in het gebed, en waakt in hetzelve met dankzegging;",
    "PSA.118.28-29": "Gij zijt mijn God, daarom zal ik U loven; o mijn God! ik zal U verhogen. Loof den HEERE, want Hij is goed; want Zijn goedertierenheid is in der eeuwigheid.",
    "ISA.12.4-5": "En zult te dienzelfden dage zeggen: Dankt den HEERE, roept Zijn Naam aan, maakt Zijn daden bekend onder de volken! vermeldt, dat Zijn Naam verhoogd is. Psalmzingt den HEERE, want Hij heeft heerlijk dingen gedaan; zulks zij bekend op den gansen aardbodem.",
    "PSA.145.1-3": "O mijn God, Gij Koning! ik zal U verhogen, en Uw Naam loven in eeuwigheid en altoos. Te allen dage zal ik U loven, en Uw Naam prijzen in eeuwigheid en altoos. De HEERE is groot en zeer te prijzen, en Zijn grootheid is ondoorgrondelijk.",
    "1CO.15.57": "Maar Gode zij dank, Die ons de overwinning geeft door onzen Heere Jezus Christus.",
    "PSA.30.11-12": "Gij hebt mij mijn weeklage veranderd in een rei; Gij hebt mijn zak ontbonden, en mij met blijdschap omgord; Opdat mijn eer U psalmzinge, en niet zwijge. HEERE, mijn God! in eeuwigheid zal ik U loven.",
    "REV.7.12": "Zeggende: Amen. De lof, en de heerlijkheid, en de wijsheid, en de dankzegging, en de eer, en de kracht, en de sterkte zij onzen God in alle eeuwigheid. Amen.",
    "PSA.103.12": "Zo ver het oosten is van het westen, zo ver doet Hij onze overtredingen van ons.",
    "COL.3.13": "Verdragende elkander, en vergevende de een den anderen, zo iemand tegen iemand enige klacht heeft; gelijkerwijs als Christus u vergeven heeft, doet ook gij alzo.",
    "MAT.6.14-15": "Want indien gij den mensen hun misdaden vergeeft, zo zal uw hemelse Vader ook u vergeven. Maar indien gij den mensen hun misdaden niet vergeeft, zo zal ook uw Vader uw misdaden niet vergeven.",
    "PSA.32.1-2": "Welgelukzalig is hij, wiens overtreding vergeven, wiens zonde bedekt is. Welgelukzalig is de mens, dien de HEERE de ongerechtigheid niet toerekent, en in wiens geest geen bedrog is.",
    "LUK.6.37": "En oordeelt niet, en gij zult niet geoordeeld worden; verdoemt niet, en gij zult niet verdoemd worden; laat los, en gij zult losgelaten worden.",
    "ACT.3.19": "Betert u dan, en bekeert u, opdat uw zonden mogen uitgewist worden; wanneer de tijden der verkoeling zullen gekomen zijn van het aangezicht des Heeren,",
    "HEB.8.12": "Want Ik zal hun ongerechtigheden genadig zijn, en hun zonden en hun overtredingen zal Ik geenszins meer gedenken.",
    "EPH.1.7": "In Welken wij hebben de verlossing door Zijn bloed, namelijk de vergeving der misdaden, naar den rijkdom Zijner genade,",
    "ISA.43.25": "Ik, Ik ben het, Die uw overtredingen uitdelg, om Mijnentwil, en Ik gedenk uwer zonden niet.",
    "MRK.11.25": "En wanneer gij staat om te bidden, vergeeft, indien gij iets hebt tegen iemand; opdat ook uw Vader, Die in de hemelen is, ulieden uw misdaden vergeve.",
    "PSA.51.1-2": "Wees mij genadig, o God! naar Uw goedertierenheid; delg mijn overtreding uit, naar de grootheid Uwer barmhartigheden. Was mij wel van mijn ongerechtigheid, en reinig mij van mijn zonde.",
    "LUK.23.34": "En Jezus zeide: Vader, vergeef het hun; want zij weten niet, wat zij doen. En verdelende Zijn klederen, wierpen zij het lot.",
    "PSA.130.3-4": "Zo Gij, HEERE! de ongerechtigheden gadeslaat; HEERE! wie zal bestaan? Maar bij U is vergeving, opdat Gij gevreesd wordt.",
    "ROM.5.20": "Maar de wet is bovendien ingekomen, opdat de misdaad te meerder worde; en waar de zonde meerder geworden is, daar is de genade veel meer overvloedig geweest;",
    "MAT.18.21-22": "Toen kwam Petrus tot Hem, en zeide: Heere! hoe menigmaal zal mijn broeder tegen mij zondigen, en ik hem vergeven! Tot zevenmaal? Jezus zeide tot hem: Ik zeg u, niet tot zevenmaal, maar tot zeventigmaal zeven maal.",
    "HEB.4.16": "Laat ons dan met vrijmoedigheid toegaan tot den troon der genade, opdat wij barmhartigheid mogen verkrijgen, en genade vinden, om geholpen te worden ter bekwamer tijd.",
    "PRO.28.13": "Die zijn overtredingen bedekt, zal niet voorspoedig zijn; maar die ze bekent en laat, zal barmhartigheid verkrijgen.",
    "ISA.55.7": "De goddeloze verlate zijn weg, en de ongerechtige man zijn gedachten; en hij bekere zich tot den HEERE, zo zal Hij Zich Zijner ontfermen, en tot onzen God, want Hij vergeeft menigvuldiglijk.",
    "DAN.9.9": "Bij den Heere, onzen God, zijn de barmhartigheden en vergevingen, alhoewel wij tegen Hem gerebelleerd hebben.",
    "1TH.5.17": "Bidt zonder ophouden.",
    "MAT.6.6": "Maar gij, wanneer gij bidt, gaat in uw binnenkamer, en uw deur gesloten hebbende, bidt uw Vader, Die in het verborgen is; en uw Vader, Die in het verborgen ziet, zal het u in het openbaar vergelden.",
    "ROM.8.26": "En desgelijks komt ook de Geest onze zwakheden mede te hulp; want wij weten niet, wat wij bidden zullen, gelijk het behoort, maar de Geest Zelf bidt voor ons met onuitsprekelijke zuchtingen.",
    "MAT.6.9-10": "Gij dan bidt aldus: Onze Vader, Die in de hemelen zijt! Uw Naam worde geheiligd. Uw Koninkrijk kome. Uw wil geschiede, gelijk in den hemel alzo ook op de aarde.",
    "PSA.17.6": "Ik roep U aan, omdat Gij mij verhoort; o God! neig Uw oor tot mij; hoor mijn rede.",
    "LUK.11.9-10": "En Ik zeg ulieden: Bidt, en u zal gegeven worden; zoekt, en gij zult vinden; klopt, en u zal opengedaan worden. Want een iegelijk, die bidt, die ontvangt; en die zoekt, die vindt; en die klopt, dien zal opengedaan worden.",
    "PSA.34.17": "Zij roepen, en de HEERE hoort, en Hij redt hen uit al hun benauwdheden.",
    "EPH.6.18": "Met alle bidding en smeking, biddende te allen tijd in den Geest, en tot hetzelve wakende met alle gedurigheid en smeking voor al de heiligen;",
    "MAT.18.19-20": "Wederom zeg Ik u: Indien er twee van u samenstemmen op de aarde, over enige zaak, die zij zouden mogen begeren, dat die hun zal geschieden van Mijn Vader, Die in de hemelen is. Want waar twee of drie vergaderd zijn in Mijn Naam, daar ben Ik in het midden van hen.",
    "PSA.55.17": "Des avonds, en des morgens, en des middags zal ik klagen en getier maken; en Hij zal mijn stem horen.",
    "PSA.66.19-20": "Maar zeker, God heeft gehoord; Hij heeft gemerkt op de stem mijns gebeds. Geloofd zij God, Die mijn gebed niet heeft afgewend, noch Zijn goedertierenheid van mij.",
    "MAT.26.41": "Waakt en bidt, opdat gij niet in verzoeking komt; de geest is wel gewillig, maar het vlees is zwak.",
    "PSA.5.3": "Des morgens, HEERE, zult Gij mijn stem horen; des morgens zal ik mij tot U schikken, en wacht houden.",
    "JHN.14.13-14": "En zo wat gij begeren zult in Mijn Naam, dat zal Ik doen; opdat de Vader in den Zoon verheerlijkt worde. Zo gij iets begeren zult in Mijn Naam, Ik zal het doen.",
    "JHN.15.7": "Indien gij in Mij blijft, en Mijn woorden in u blijven, zo wat gij wilt, zult gij begeren, en het zal u geschieden.",
    "PSA.141.2": "Mijn gebed worde gesteld als reukwerk voor Uw aangezicht, de opheffing mijner handen als het avondoffer.",
    "1TI.2.1-2": "Ik vermaan dan voor alle dingen, dat gedaan worden smekingen, gebeden, voorbiddingen, dankzeggingen, voor alle mensen; Voor koningen, en allen, die in hoogheid zijn; opdat wij een gerust en stil leven leiden mogen in alle godzaligheid en eerbaarheid.",
    "LUK.18.1": "En Hij zeide ook een gelijkenis tot hen, daartoe strekkende, dat men altijd bidden moet, en niet vertragen;",
    "PSA.102.17": "Zich gewend zal hebben tot het gebed desgenen, die gans ontbloot is, en niet versmaad hebben hunlieder gebed;",
    "JHN.15.11": "Deze dingen heb Ik tot u gesproken, opdat Mijn blijdschap in u blijve, en uw blijdschap vervuld worde.",
    "JAS.1.2-3": "Acht het voor grote vreugde, mijn broeders, wanneer gij in velerlei verzoekingen valt; Wetende, dat de beproeving uws geloofs lijdzaamheid werkt.",
    "PSA.126.5-6": "Die met tranen zaaien, zullen met gejuich maaien. Die het zaad draagt, dat men zaaien zal, gaat al gaande en wenende; maar voorzeker zal hij met gejuich wederkomen, dragende zijn schoven.",
    "1PE.1.8-9": "Denwelken gij niet gezien hebt, en nochtans liefhebt, in Denwelken gij nu, hoewel Hem niet ziende, maar gelovende, u verheugt met een onuitsprekelijke en heerlijke vreugde; Verkrijgende het einde uws geloofs, namelijk de zaligheid der zielen.",
    "PSA.5.11": "Maar laat verblijd zijn allen, die op U betrouwen, tot in eeuwigheid; laat hen juichen, omdat Gij hen overdekt; en laat in U van vreugde opspringen, die Uw Naam liefhebben.",
    "JHN.16.22": "En gij dan hebt nu wel droefheid; maar Ik zal u wederom zien, en uw hart zal zich verblijden, en niemand zal uw blijdschap van u wegnemen.",
    "ISA.61.10": "Ik ben zeer vrolijk in den HEERE, mijn ziel verheugt zich in mijn God, want Hij heeft mij bekleed met de klederen des heils, den mantel der gerechtigheid heeft Hij mij omgedaan; gelijk een bruidegom zich met priesterlijk sieraad versiert, en als een bruid zich versiert met haar gereedschap.",
    "PSA.100.1-2": "Gij ganse aarde! juicht den HEERE. Dient den HEERE met blijdschap, komt voor Zijn aanschijn met vrolijk gezang.",
    "PSA.32.11": "Verblijdt u in den HEERE, en verheugt u, gij rechtvaardigen! en zingt vrolijk, alle gij oprechten van harte!",
    "1TH.5.16": "Verblijdt u te allen tijd.",
    "PSA.51.12": "Geef mij weder de vreugde Uws heils; en de vrijmoedige geest ondersteune mij.",
    "ISA.12.3": "En gijlieden zult water scheppen met vreugde uit de fonteinen des heils;",
    "PSA.47.1": "Al gij volken, klapt in de hand; juicht Gode met een stem van vreugdegezang.",
    "LUK.15.10": "Alzo, zeg Ik ulieden, is er blijdschap voor de engelen Gods over een zondaar, die zich bekeert.",
    "PSA.97.11-12": "Het licht is voor den rechtvaardige gezaaid, en vrolijkheid voor de oprechten van hart. Gij rechtvaardigen! verblijdt u in den HEERE, en spreekt lof ter gedachtenis Zijner heiligheid.",
    "JHN.16.24": "Tot nog toe hebt gij niet gebeden in Mijn Naam; bidt, en gij zult ontvangen, opdat uw blijdschap vervuld zij."
};
